window.MR={"B8": {"ten": "Bài 8. Chuyển động biến đổi. Gia tốc", "nhom": [{"ten": "", "lt": "", "I": [{"than": "<p>Vectơ gia tốc <span class=\"m\">\\vec{a}</span> có tính chất nào kể sau?</p>", "lc": [["A", "Đặc trưng cho sự biến thiên của vận tốc."], ["B", "Cùng chiều với <span class=\"m\">\\vec{v}</span> nếu chuyển động nhanh dần."], ["C", "Ngược chiều với <span class=\"m\">\\vec{v}</span> nếu chuyển động chậm dần."], ["D", "Các tính chất A, B, C."]], "ds": [], "tr": 22, "col": 1, "da": "D", "lg": ["Gia tốc đặc trưng cho sự biến thiên của vận tốc; NDĐ thì <span class=\"m\">\\vec a</span> cùng chiều <span class=\"m\">\\vec v</span>, CDĐ thì ngược chiều."]}, {"than": "<p>Gia tốc là một đại lượng</p>", "lc": [["A", "đại số, đặc trưng cho sự biến đổi nhanh hay chậm của chuyển động."], ["B", "đại số, đặc trưng cho tính không đổi của vận tốc."], ["C", "vectơ, đặc trưng cho sự biến đổi nhanh hay chậm của chuyển động."], ["D", "vectơ, đặc trưng cho sự biến đổi nhanh hay chậm của vận tốc."]], "ds": [], "tr": 22, "col": 1, "da": "D", "lg": ["Gia tốc là đại lượng vectơ, đặc trưng cho sự biến đổi nhanh hay chậm của vận tốc."]}, {"than": "<p>(SBT-KNTT) Chuyển động nào sau đây là chuyển động biến đổi?</p>", "lc": [["A", "Chuyển động có độ dịch chuyển tăng đều theo thời gian."], ["B", "Chuyển động có độ dịch chuyển giảm đều theo thời gian."], ["C", "Chuyển động có độ dịch chuyển không đổi theo thời gian."], ["D", "Chuyển động tròn đều."]], "ds": [], "tr": 22, "col": 1, "da": "D", "lg": ["Độ dịch chuyển tăng/giảm đều là chuyển động thẳng đều. Chuyển động tròn đều có vận tốc đổi hướng nên là chuyển động biến đổi."]}, {"than": "<p>(SBT-KNTT) Chuyển động nào sau đây không phải là chuyển động biến đổi đều?</p><figure><img src=\"k10-c2-mr/h/t23_190_445.jpg\" width=\"425\" height=\"250\" style=\"width:3.44cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"><img src=\"k10-c2-mr/h/t23_630_430.jpg\" width=\"185\" height=\"360\" style=\"width:1.50cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"><img src=\"k10-c2-mr/h/t23_1160_500.jpg\" width=\"395\" height=\"350\" style=\"width:3.20cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"><img src=\"k10-c2-mr/h/t23_1570_500.jpg\" width=\"130\" height=\"350\" style=\"width:1.05cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Viên bi lăn xuống trên máng nghiêng."], ["B", "Vật rơi từ trên cao xuống đất."], ["C", "Hòn đá bị ném theo phương nằm ngang."], ["D", "Quả bóng được ném lên theo phương thẳng đứng."]], "ds": [], "tr": 23, "col": 1, "da": "C", "lg": ["Hòn đá ném ngang chuyển động theo quỹ đạo cong, độ lớn vận tốc không biến đổi đều theo thời gian."]}, {"than": "<p>(SBT-CTST) Một xe máy đang đứng yên, sau đó khởi động và bắt đầu tăng tốc. Nếu chọn chiều dương là chiều chuyển động của xe, nhận xét nào sau đây là <b>đúng</b>?</p>", "lc": [["A", "<span class=\"m\">a>0,\\ v>0</span>."], ["B", "<span class=\"m\">a&lt;0,\\ v&lt;0</span>."], ["C", "<span class=\"m\">a>0,\\ v&lt;0</span>."], ["D", "<span class=\"m\">a&lt;0,\\ v>0</span>."]], "ds": [], "tr": 23, "col": 4, "da": "A", "lg": ["Xe tăng tốc theo chiều dương: <span class=\"m\">v>0</span>, <span class=\"m\">a</span> cùng dấu <span class=\"m\">v</span> nên <span class=\"m\">a>0</span>."]}, {"than": "<p>Chọn câu <b>sai</b>. Chất điểm chuyển động theo một chiều với gia tốc <span class=\"m\">a=4\\ \\text{m/s}^2</span> có nghĩa là</p>", "lc": [["A", "Lúc đầu vận tốc bằng 0 thì sau 1 s vận tốc của nó bằng 4 m/s."], ["B", "Lúc vận tốc bằng 2 m/s thì sau 1 s vận tốc của nó bằng 6 m/s."], ["C", "Lúc vận tốc bằng 2 m/s thì sau 2 s vận tốc của nó bằng 8 m/s."], ["D", "Lúc vận tốc bằng 4 m/s thì sau 2 s vận tốc của nó bằng 12 m/s."]], "ds": [], "tr": 23, "col": 1, "da": "C", "lg": ["Sau 2 s vận tốc tăng <span class=\"m\">4\\cdot 2=8</span> m/s: từ 2 m/s lên 10 m/s chứ không phải 8 m/s."]}, {"than": "<p>Một xe lửa bắt đầu rời khỏi ga và chuyển động thẳng nhanh dần đều với gia tốc 0,1 m/s². Khoảng thời gian để xe đạt được vận tốc 36 km/h là:</p>", "lc": [["A", "<span class=\"m\">t=360\\ \\text{s}</span>."], ["B", "<span class=\"m\">t=200\\ \\text{s}</span>."], ["C", "<span class=\"m\">t=300\\ \\text{s}</span>."], ["D", "<span class=\"m\">t=100\\ \\text{s}</span>."]], "ds": [], "tr": 24, "col": 4, "da": "D", "lg": ["<span class=\"m\">t=\\dfrac{v-v_0}{a}=\\dfrac{10-0}{0{,}1}=100</span> s."]}, {"than": "<p>Gia tốc là một đại lượng</p>", "lc": [["A", "đại số, đặc trưng cho sự biến thiên nhanh hay chậm của chuyển động."], ["B", "đại số, đặc trưng cho tính không đổi của vận tốc."], ["C", "vectơ, đặc trưng cho sự biến thiên nhanh hay chậm của chuyển động."], ["D", "vectơ, đặc trưng cho sự biến thiên nhanh hay chậm của vận tốc."]], "ds": [], "tr": 26, "col": 1, "da": "D", "lg": ["Gia tốc là đại lượng vectơ, đặc trưng cho sự biến thiên nhanh hay chậm của vận tốc."]}, {"than": "<p>Véctơ gia tốc <span class=\"m\">\\vec{a}</span> có tính chất nào kể sau?</p>", "lc": [["A", "Đặc trưng cho sự biến thiên của vận tốc."], ["B", "Cùng chiều với <span class=\"m\">\\vec{v}</span> nếu chuyển động nhanh dần."], ["C", "Ngược chiều với <span class=\"m\">\\vec{v}</span> nếu chuyển động chậm dần."], ["D", "Các tính chất trên."]], "ds": [], "tr": 33, "col": 1, "da": "D", "lg": ["Gia tốc đặc trưng cho sự biến thiên của vận tốc; NDĐ thì <span class=\"m\">\\vec a</span> cùng chiều <span class=\"m\">\\vec v</span>, CDĐ thì ngược chiều."]}], "II": [{"than": "<p>Một ô tô tải đang chạy trên đường thẳng với vận tốc 18 km/h thì tăng dần đều vận tốc. Sau 20 s ô tô đạt được vận tốc 36 km/h.</p>", "lc": [], "ds": [["a", "Gia tốc của ô tô được xác định bằng biểu thức <span class=\"m\">a=\\dfrac{v-v_0}{t}</span>."], ["b", "Gia tốc của ô tô là 2,5 m/s²."], ["c", "Vận tốc ô tô đạt được sau 40 s là 20 m/s."], ["d", "Sau 60 s kể từ khi tăng tốc, ô tô đạt vận tốc 72 km/h."]], "tr": 25, "col": 0, "da": "Đ S S Đ", "lg": ["<span class=\"m\">v_0=5</span> m/s, <span class=\"m\">v=10</span> m/s: <span class=\"m\">a=\\dfrac{10-5}{20}=0{,}25</span> m/s². Sau 40 s: <span class=\"m\">v=5+0{,}25\\cdot 40=15</span> m/s. Sau 60 s: <span class=\"m\">v=5+0{,}25\\cdot 60=20</span> m/s <span class=\"m\">=72</span> km/h."]}], "III": [{"than": "<p>Một người lái xe máy đang chạy xe với vận tốc 36 km/h thì nhìn thấy một cái hố sâu trước mặt. Người ấy kịp thời phanh gấp xe thì xe tiếp tục chạy thêm 3 s nữa mới dừng lại. Tính gia tốc trung bình của xe theo đơn vị m/s²? (kết quả lấy 1 chữ số sau dấu phẩy thập phân)</p>", "lc": [], "ds": [], "tr": 25, "col": 0, "da": "−3,3 (độ lớn 3,3)", "lg": ["<span class=\"m\">v_0=36</span> km/h <span class=\"m\">=10</span> m/s; <span class=\"m\">a=\\dfrac{0-10}{3}\\approx -3{,}3</span> m/s²."]}]}], "dem": {"I": 9, "II": 1, "III": 1}, "word": "k10-c2-mr/word/Bai08_Gia_toc_Mo_rong.docx", "wordDa": "k10-c2-mr/word/Bai08_Gia_toc_Mo_rong_Dap_an.docx"}, "B9": {"ten": "Bài 9. Chuyển động thẳng biến đổi đều", "nhom": [{"ten": "Phương trình và công thức của chuyển động thẳng biến đổi đều", "lt": "", "I": [{"than": "<p>Trong chuyển động thẳng nhanh dần đều:</p>", "lc": [["A", "Vận tốc tăng đến cực đại rồi giảm dần."], ["B", "Vận tốc của vật tỉ lệ với bình phương thời gian."], ["C", "Gia tốc tăng đều theo thời gian."], ["D", "Vận tốc tăng đều theo thời gian."]], "ds": [], "tr": 22, "col": 1, "da": "D", "lg": ["NDĐ: <span class=\"m\">v=v_0+at</span> với <span class=\"m\">a</span> không đổi nên vận tốc tăng đều theo thời gian."]}, {"than": "<p>Trong chuyển động biến đổi đều thì</p>", "lc": [["A", "gia tốc là một đại lượng không đổi."], ["B", "gia tốc là đại lượng biến thiên theo thời gian."], ["C", "vận tốc là đại lượng không đổi."], ["D", "vận tốc là đại lượng biến thiên theo thời gian theo quy luật hàm bậc hai."]], "ds": [], "tr": 22, "col": 1, "da": "A", "lg": ["Chuyển động biến đổi đều có gia tốc không đổi."]}, {"than": "<p>(SBT-KNTT) Công thức liên hệ giữa độ dịch chuyển, vận tốc và gia tốc của chuyển động nhanh dần đều là</p>", "lc": [["A", "<span class=\"m\">v^2-v_0^2=ad</span>."], ["B", "<span class=\"m\">v^2-v_0^2=2ad</span>."], ["C", "<span class=\"m\">v-v_0=2ad</span>."], ["D", "<span class=\"m\">v_0^2-v^2=2ad</span>."]], "ds": [], "tr": 23, "col": 4, "da": "B", "lg": ["<span class=\"m\">v^2-v_0^2=2ad</span>."]}, {"than": "<p>(SBT-KNTT) Chuyển động thẳng chậm dần đều có tính chất nào sau đây?</p>", "lc": [["A", "Độ dịch chuyển giảm dần đều theo thời gian."], ["B", "Vận tốc giảm đều theo thời gian."], ["C", "Gia tốc giảm đều theo thời gian."], ["D", "Cả 3 tính chất trên."]], "ds": [], "tr": 23, "col": 1, "da": "B", "lg": ["CDĐ: độ lớn vận tốc giảm đều theo thời gian, gia tốc không đổi."]}, {"than": "<p>(SBT-KNTT) Trong chuyển động thẳng biến đổi đều, gia tốc</p>", "lc": [["A", "có giá trị bằng 0."], ["B", "là một hằng số khác 0."], ["C", "có giá trị biến thiên theo thời gian."], ["D", "chỉ thay đổi hướng chứ không thay đổi về độ lớn."]], "ds": [], "tr": 23, "col": 1, "da": "B", "lg": ["Gia tốc là hằng số khác 0."]}, {"than": "<p>Phương trình nào sau đây là phương trình độ dịch chuyển của một vật chuyển động thẳng chậm dần đều dọc theo trục Ox?</p>", "lc": [["A", "<span class=\"m\">s=2t-3t^2</span>."], ["B", "<span class=\"m\">d=5t^2-2t</span>."], ["C", "<span class=\"m\">v=4-t</span>."], ["D", "<span class=\"m\">x=2-5t-t^2</span>."]], "ds": [], "tr": 23, "col": 4, "da": "A", "lg": ["<span class=\"m\">s=2t-3t^2</span>: <span class=\"m\">v_0=2</span> m/s, <span class=\"m\">a=-6</span> m/s², <span class=\"m\">a.v_0&lt;0</span> nên chậm dần đều. (Ghi chú: ở B, <span class=\"m\">v_0=-2</span> m/s, <span class=\"m\">a=10</span> m/s² cũng trái dấu nên vật chậm dần trong 0,2 s đầu rồi nhanh dần; D nhanh dần; C là phương trình vận tốc.)"]}, {"than": "<p>Một người bắt đầu chuyển động thẳng biến đổi đều từ trung tâm Tô Hoàng ra Cầu Giấy. Đến Cầu Giấy học sinh có vận tốc 2 m/s. Hỏi khi về đến nhà học sinh có vận tốc bao nhiêu? Biết rằng Cầu Giấy về đến nhà bằng ba lần từ trung tâm Tô Hoàng ra Cầu Giấy.</p>", "lc": [["A", "3 m/s"], ["B", "4 m/s"], ["C", "1 m/s"], ["D", "0,5 m/s"]], "ds": [], "tr": 23, "col": 4, "da": "B", "lg": ["<span class=\"m\">v_1^2=2as</span>; <span class=\"m\">v_2^2=2a(s+3s)=4v_1^2</span> ⇒ <span class=\"m\">v_2=2v_1=4</span> m/s."]}, {"than": "<p>Một máy bay chở khách muốn cất cánh được phải chạy trên đường băng dài 1,8 km để đạt được vận tốc 300 km/h. Máy bay có gia tốc không đổi tối thiểu là</p><figure><img src=\"k10-c2-mr/h/t24_1255_215.jpg\" width=\"620\" height=\"365\" style=\"width:5.02cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "50000 km/h²"], ["B", "50000 m/s²"], ["C", "25000 km/h²"], ["D", "25000 m/s²"]], "ds": [], "tr": 24, "col": 4, "da": "C", "lg": ["<span class=\"m\">a=\\dfrac{v^2}{2s}=\\dfrac{300^2}{2\\cdot 1{,}8}=25000</span> km/h²."]}, {"than": "<p>Một đoàn tàu rời ga chuyển động thẳng nhanh dần đều. Sau 1 phút tàu đạt tốc độ 40 km/h. Tính gia tốc và độ dời mà đoàn tàu đi được trong 1 phút đó.</p><figure><img src=\"k10-c2-mr/h/t24_1295_785.jpg\" width=\"505\" height=\"315\" style=\"width:4.09cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "0,1 m/s²; 300 m"], ["B", "0,3 m/s²; 330 m"], ["C", "0,2 m/s²; 340 m"], ["D", "0,185 m/s²; 333 m"]], "ds": [], "tr": 24, "col": 4, "da": "D", "lg": ["<span class=\"m\">v=40</span> km/h <span class=\"m\">\\approx 11{,}1</span> m/s; <span class=\"m\">a=\\dfrac{11{,}1}{60}\\approx 0{,}185</span> m/s²; <span class=\"m\">d=\\dfrac{1}{2}at^2\\approx 333</span> m."]}, {"than": "<p>Quả cầu lăn từ đỉnh dốc dài 1 m, sau 10 s đến chân dốc. Sau đó quả cầu lăn trên mặt phẳng nằm ngang được 2 m thì dừng lại. Chiều dương là chiều chuyển động. Gia tốc của quả cầu trên dốc và trên mặt phẳng ngang lần lượt là</p><figure><img src=\"k10-c2-mr/h/t24_1205_1105.jpg\" width=\"645\" height=\"345\" style=\"width:5.22cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "−0,02 m/s²; 0,01 m/s²."], ["B", "−0,01 m/s²; 0,02 m/s²."], ["C", "0,01 m/s²; −0,02 m/s²."], ["D", "0,02 m/s²; −0,01 m/s²."]], "ds": [], "tr": 24, "col": 2, "da": "D", "lg": ["Trên dốc: <span class=\"m\">a_1=\\dfrac{2s}{t^2}=\\dfrac{2\\cdot 1}{10^2}=0{,}02</span> m/s², <span class=\"m\">v=a_1t=0{,}2</span> m/s. Trên mặt ngang: <span class=\"m\">a_2=\\dfrac{0-0{,}2^2}{2\\cdot 2}=-0{,}01</span> m/s²."]}, {"than": "<p>(SBT-CTST) Xét hai xe A và B chuyển động cùng nhau vào hầm Thủ Thiêm dài 1490 m. Xe A chuyển động với tốc độ ban đầu trước khi vào hầm là 60 km/h và chuyển động chậm dần đều với gia tốc 144 km/h², xe B chuyển động chậm dần đều với gia tốc 120 km/h² từ lúc bắt đầu chạy vào hầm với tốc độ 55 km/h. Nhận định nào sau đây là đúng về thời gian chuyển động của hai xe trong hầm?</p><figure><img src=\"k10-c2-mr/h/t24_1110_1915.jpg\" width=\"765\" height=\"415\" style=\"width:6.19cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Hai xe đi hết hầm Thủ Thiêm cùng một khoảng thời gian."], ["B", "Xe B ra khỏi hầm trước xe A."], ["C", "Xe A ra khỏi hầm trước xe B."], ["D", "Dữ liệu bài toán không đủ kết luận."]], "ds": [], "tr": 24, "col": 1, "da": "C", "lg": ["Xe A: <span class=\"m\">1{,}49=60t-72t^2</span> ⇒ <span class=\"m\">t_A\\approx 0{,}0256</span> h <span class=\"m\">\\approx 92</span> s. Xe B: <span class=\"m\">1{,}49=55t-60t^2</span> ⇒ <span class=\"m\">t_B\\approx 0{,}0279</span> h <span class=\"m\">\\approx 101</span> s. Xe A ra khỏi hầm trước."]}, {"than": "<p>Vectơ gia tốc của chuyển động thẳng biến đổi đều</p>", "lc": [["A", "có phương vuông góc với vectơ vận tốc."], ["B", "có độ lớn không đổi."], ["C", "cùng hướng với vectơ vận tốc."], ["D", "ngược hướng với vectơ vận tốc."]], "ds": [], "tr": 27, "col": 2, "da": "B", "lg": ["Chuyển động thẳng biến đổi đều có gia tốc không đổi (cả hướng và độ lớn)."]}, {"than": "<p>Phương trình chuyển động của một vật trên trục Ox có dạng: <span class=\"m\">x=-2t^2+15t+10</span>. Trong đó t tính bằng giây, x tính bằng mét. Vật này chuyển động</p>", "lc": [["A", "nhanh dần đều rồi chậm dần đều theo chiều âm của trục Ox."], ["B", "chậm dần đều theo chiều dương rồi nhanh dần đều theo chiều âm của trục Ox."], ["C", "nhanh dần đều rồi chậm dần đều theo chiều dương của trục Ox."], ["D", "chậm dần đều rồi nhanh dần đều theo chiều âm của trục Ox."]], "ds": [], "tr": 27, "col": 1, "da": "B", "lg": ["<span class=\"m\">v_0=15</span> m/s <span class=\"m\">>0</span>, <span class=\"m\">a=-4</span> m/s² <span class=\"m\">&lt;0</span>: chậm dần đều theo chiều dương đến <span class=\"m\">t=3{,}75</span> s rồi nhanh dần đều theo chiều âm."]}, {"than": "<p>Một vật chuyển động thẳng chậm dần đều có vận tốc ban đầu <span class=\"m\">v_0</span>, gia tốc có độ lớn a không đổi, phương trình vận tốc có dạng: <span class=\"m\">v=v_0+at</span>. Vật này có</p>", "lc": [["A", "tích <span class=\"m\">v.a>0</span>."], ["B", "a luôn dương."], ["C", "v tăng theo thời gian."], ["D", "a luôn ngược dấu với v."]], "ds": [], "tr": 27, "col": 2, "da": "D", "lg": ["Chậm dần đều thì <span class=\"m\">a.v&lt;0</span>: <span class=\"m\">a</span> luôn ngược dấu với <span class=\"m\">v</span>."]}, {"than": "<p>Một vật chuyển động trên đoạn thẳng, tại một thời điểm vật có vận tốc v và gia tốc a. Chuyển động có</p>", "lc": [["A", "gia tốc a âm là chuyển động chậm dần đều."], ["B", "gia tốc a dương là chuyển động nhanh dần đều."], ["C", "<span class=\"m\">a.v&lt;0</span> là chuyển động chậm dần đều."], ["D", "vận tốc v âm là chuyển động nhanh dần đều."]], "ds": [], "tr": 27, "col": 1, "da": "C", "lg": ["<span class=\"m\">a.v&lt;0</span>: chuyển động chậm dần đều; dấu của riêng <span class=\"m\">a</span> hay <span class=\"m\">v</span> không cho biết nhanh hay chậm dần."]}, {"than": "<p>Với chiều (+) là chiều chuyển động, trong công thức <span class=\"m\">d=v_0t+\\dfrac{at^2}{2}</span> của chuyển động thẳng biến đổi đều, đại lượng có thể có giá trị dương hay giá trị âm là:</p>", "lc": [["A", "Gia tốc."], ["B", "Quãng đường."], ["C", "Vận tốc."], ["D", "Thời gian."]], "ds": [], "tr": 27, "col": 4, "da": "A", "lg": ["Với chiều dương là chiều chuyển động thì <span class=\"m\">d,\\ v_0,\\ t</span> đều dương; chỉ gia tốc có thể dương (NDĐ) hoặc âm (CDĐ)."]}, {"than": "<p>Chọn phát biểu <b>sai</b>.</p>", "lc": [["A", "Trong chuyển động thẳng biến đổi đều, quãng đường đi được trong những khoảng thời gian bằng nhau thì bằng nhau."], ["B", "Gia tốc của chuyển động thẳng biến đổi đều có độ lớn không đổi."], ["C", "Vectơ gia tốc của chuyển động thẳng biến đổi đều có thể cùng chiều hoặc ngược chiều với vectơ vận tốc."], ["D", "Vận tốc tức thời của chuyển động thẳng biến đổi đều có độ lớn tăng hoặc giảm đều theo thời gian."]], "ds": [], "tr": 27, "col": 1, "da": "A", "lg": ["Quãng đường đi được trong những khoảng thời gian bằng nhau bằng nhau là đặc điểm của chuyển động thẳng đều."]}, {"than": "<p>Công thức tính quãng đường đi được của chuyển động thẳng nhanh dần đều là</p>", "lc": [["A", "<span class=\"m\">s=v_0t+\\dfrac{1}{2}at^2</span> (a và <span class=\"m\">v_0</span> cùng dấu)."], ["B", "<span class=\"m\">s=v_0t+\\dfrac{1}{2}at^2</span> (a và <span class=\"m\">v_0</span> trái dấu)."], ["C", "<span class=\"m\">x=x_0+v_0t+\\dfrac{1}{2}at^2</span> (a và <span class=\"m\">v_0</span> cùng dấu)."], ["D", "<span class=\"m\">x=x_0+v_0t+\\dfrac{1}{2}at^2</span> (a và <span class=\"m\">v_0</span> trái dấu)."]], "ds": [], "tr": 27, "col": 1, "da": "A", "lg": ["NDĐ: <span class=\"m\">a</span> cùng dấu <span class=\"m\">v_0</span>; quãng đường <span class=\"m\">s=v_0t+\\dfrac{1}{2}at^2</span>."]}, {"than": "<p>Phương trình của chuyển động thẳng chậm dần đều là</p>", "lc": [["A", "<span class=\"m\">x=v_0t+\\dfrac{1}{2}at^2</span> (a và <span class=\"m\">v_0</span> cùng dấu)."], ["B", "<span class=\"m\">x=v_0t+\\dfrac{1}{2}at^2</span> (a và <span class=\"m\">v_0</span> trái dấu)."], ["C", "<span class=\"m\">x=x_0+v_0t+\\dfrac{1}{2}at^2</span> (a và <span class=\"m\">v_0</span> cùng dấu)."], ["D", "<span class=\"m\">x=x_0+v_0t+\\dfrac{1}{2}at^2</span> (a và <span class=\"m\">v_0</span> trái dấu)."]], "ds": [], "tr": 28, "col": 1, "da": "D", "lg": ["Phương trình chuyển động: <span class=\"m\">x=x_0+v_0t+\\dfrac{1}{2}at^2</span>; chậm dần đều khi <span class=\"m\">a</span> và <span class=\"m\">v_0</span> trái dấu."]}, {"than": "<p>Trong công thức liên hệ giữa quãng đường đi được, vận tốc và gia tốc (<span class=\"m\">v^2-v_0^2=2as</span>) của chuyển động thẳng nhanh dần đều, ta có các điều kiện nào dưới đây?</p>", "lc": [["A", "<span class=\"m\">s>0;\\ a>0;\\ v>v_0</span>."], ["B", "<span class=\"m\">s>0;\\ a&lt;0;\\ v&lt;v_0</span>."], ["C", "<span class=\"m\">s>0;\\ a>0;\\ v&lt;v_0</span>."], ["D", "<span class=\"m\">s>0;\\ a&lt;0;\\ v>v_0</span>."]], "ds": [], "tr": 28, "col": 2, "da": "A", "lg": ["NDĐ (chiều dương là chiều chuyển động): <span class=\"m\">s>0,\\ a>0,\\ v>v_0</span>."]}, {"than": "<p>Một xe ô tô chuyển động thẳng nhanh dần đều với vận tốc đầu 18 km/h. Trong giây thứ tư kể từ lúc bắt đầu chuyển động nhanh dần, xe đi được 12 m. Hãy tính gia tốc của vật?</p>", "lc": [["A", "1 m/s²"], ["B", "2 m/s²."], ["C", "−1 m/s²."], ["D", "−2 m/s²"]], "ds": [], "tr": 28, "col": 4, "da": "B", "lg": ["<span class=\"m\">v_0=5</span> m/s. Giây thứ tư: <span class=\"m\">s_4-s_3=v_0+\\dfrac{a}{2}(4^2-3^2)=5+3{,}5a=12</span> ⇒ <span class=\"m\">a=2</span> m/s²."]}, {"than": "<p>Một vật bắt đầu chuyển động nhanh dần đều trong 10 s với gia tốc của vật 2 m/s². Quãng đường vật đi được trong 2 s cuối cùng là bao nhiêu?</p>", "lc": [["A", "16 m"], ["B", "26 m"], ["C", "36 m"], ["D", "44 m"]], "ds": [], "tr": 28, "col": 4, "da": "C", "lg": ["<span class=\"m\">s_{10}=\\dfrac{1}{2}\\cdot 2\\cdot 10^2=100</span> m; <span class=\"m\">s_8=64</span> m ⇒ 2 s cuối đi được 36 m."]}, {"than": "<p>Một ô tô xuống dốc nhanh dần đều không vận tốc đầu. Trong giây thứ 5 nó đi được 13,5 m. Gia tốc của ô tô là</p>", "lc": [["A", "3 m/s²."], ["B", "1,08 m/s²."], ["C", "27 m/s²."], ["D", "2,16 m/s²."]], "ds": [], "tr": 28, "col": 4, "da": "A", "lg": ["Giây thứ 5: <span class=\"m\">\\dfrac{a}{2}(5^2-4^2)=4{,}5a=13{,}5</span> ⇒ <span class=\"m\">a=3</span> m/s²."]}, {"than": "<p>Một xe ô tô chuyển động thẳng nhanh dần đều với vận tốc đầu 18 km/h. Trong giây thứ tư kể từ lúc bắt đầu chuyển động nhanh dần, xe đi được 12 m. Hãy tính quãng đường đi được sau 10 s.</p>", "lc": [["A", "120 m"], ["B", "130 m"], ["C", "140 m"], ["D", "150 m"]], "ds": [], "tr": 28, "col": 4, "da": "D", "lg": ["Như câu trước: <span class=\"m\">v_0=5</span> m/s, <span class=\"m\">a=2</span> m/s² ⇒ <span class=\"m\">s=5\\cdot 10+\\dfrac{1}{2}\\cdot 2\\cdot 10^2=150</span> m."]}, {"than": "<p>Một ô tô bắt đầu chuyển động thẳng nhanh dần đều. Trong giây thứ 6 xe đi được quãng đường 11 m. Tính gia tốc của xe.</p>", "lc": [["A", "2 m/s²"], ["B", "4 m/s²"], ["C", "5 m/s²"], ["D", "3 m/s²"]], "ds": [], "tr": 28, "col": 4, "da": "A", "lg": ["Giây thứ 6: <span class=\"m\">\\dfrac{a}{2}(6^2-5^2)=5{,}5a=11</span> ⇒ <span class=\"m\">a=2</span> m/s²."]}, {"than": "<p>Trên đường thẳng, ô tô chuyển động nhanh dần đều trên hai đoạn đường liên tiếp bằng nhau và bằng 150 m, lần lượt trong 6 s và 3 s. Gia tốc của ô tô <b>gần giá trị nào nhất</b> sau đây?</p><figure><img src=\"k10-c2-mr/h/t28_60_2580.jpg\" width=\"1280\" height=\"195\" style=\"width:10.36cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "7,2 m/s²."], ["B", "2,1 m/s²."], ["C", "5,6 m/s²."], ["D", "4,3 m/s²."]], "ds": [], "tr": 28, "col": 4, "da": "C", "lg": ["Đoạn 1: <span class=\"m\">6v_0+18a=150</span>. Cả hai đoạn: <span class=\"m\">9v_0+40{,}5a=300</span>. Giải ra <span class=\"m\">a\\approx 5{,}56</span> m/s²."]}, {"than": "<p>Từ trạng thái đứng yên, một vật chuyển động nhanh dần đều với gia tốc là 2 m/s² và đi được quãng đường dài 100 m. Hãy chia quãng đường đó ra làm 2 phần sao cho vật đi được 2 phần đó trong 2 khoảng thời gian bằng nhau:</p>", "lc": [["A", "50 m, 50 m"], ["B", "40 m, 60 m"], ["C", "32 m, 68 m"], ["D", "25 m, 75 m"]], "ds": [], "tr": 29, "col": 4, "da": "D", "lg": ["Từ nghỉ, hai khoảng thời gian bằng nhau đi được quãng đường tỉ lệ <span class=\"m\">1:3</span> ⇒ 25 m và 75 m."]}, {"than": "<p>Một người đứng ở sân ga nhìn đoàn tàu bắt đầu chuyển bánh nhanh dần đều trên một đường thẳng thì thấy toa thứ nhất đi qua trước mặt mình trong 3 giây. Trong thời gian Δt toa thứ 15 đi qua trước mặt người ấy, Δt <b>gần giá trị nào nhất</b> sau đây?</p>", "lc": [["A", "0,4 s."], ["B", "0,5 s."], ["C", "0,3 s."], ["D", "0,7 s."]], "ds": [], "tr": 29, "col": 4, "da": "A", "lg": ["Toa thứ <span class=\"m\">n</span> qua trong <span class=\"m\">\\Delta t=t_1(\\sqrt n-\\sqrt{n-1})=3(\\sqrt{15}-\\sqrt{14})\\approx 0{,}39</span> s."]}], "II": [{"than": "<p>Một quả cầu bắt đầu lăn từ đỉnh một dốc dài 100 m, sau 10 s thì nó đến chân dốc. Sau đó nó tiếp tục chuyển động trên mặt ngang được 50 m thì dừng lại. Chọn chiều dương là chiều chuyển động của quả cầu.</p><figure><img src=\"k10-c2-mr/h/t25_640_165.jpg\" width=\"1060\" height=\"445\" style=\"width:8.58cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Gia tốc của quả cầu khi lăn trên dốc là 2,5 m/s²."], ["b", "Vận tốc của quả cầu tại chân dốc 20 m/s."], ["c", "Gia tốc của quả cầu khi lăn trên mặt ngang 4 m/s²."], ["d", "Thời gian quả cầu lăn trên mặt ngang 5 s."]], "tr": 24, "col": 0, "da": "S Đ S Đ", "lg": ["Trên dốc: <span class=\"m\">a_1=\\dfrac{2\\cdot 100}{10^2}=2</span> m/s²; <span class=\"m\">v=a_1t=20</span> m/s. Trên mặt ngang: <span class=\"m\">a_2=\\dfrac{0-20^2}{2\\cdot 50}=-4</span> m/s² (ngược chiều dương, nên c sai về dấu); <span class=\"m\">t=\\dfrac{0-20}{-4}=5</span> s."]}, {"than": "<p>Một ô tô chạy với tốc độ 54 km/h trên đoạn đường thẳng thì người lái xe hãm phanh cho ô tô chạy thẳng chậm dần đều. Sau khi chạy thêm 250 m thì tốc độ của ô tô chỉ còn 5 m/s.</p>", "lc": [], "ds": [["a", "Vận tốc ban đầu của ô tô trước khi hãm phanh là 20 m/s."], ["b", "Gia tốc của ô tô là 0,4 m/s²."], ["c", "Sau 25 s kể từ khi hãm phanh, xe đi được 250 m."], ["d", "Sau 37,5 s kể từ lúc hãm phanh, xe dừng hẳn."]], "tr": 25, "col": 0, "da": "S Đ Đ Đ", "lg": ["<span class=\"m\">v_0=54</span> km/h <span class=\"m\">=15</span> m/s. <span class=\"m\">a=\\dfrac{5^2-15^2}{2\\cdot 250}=-0{,}4</span> m/s² (chọn chiều dương là chiều chuyển động), độ lớn 0,4 m/s²: đề không chọn chiều dương nên ý b xét theo độ lớn. Sau 25 s: <span class=\"m\">v=15-0{,}4\\cdot 25=5</span> m/s, đúng lúc đi được 250 m. Dừng khi <span class=\"m\">t=\\dfrac{15}{0{,}4}=37{,}5</span> s."]}, {"than": "<p>Một xe đạp đang đi với vận tốc 2 m/s thì xuống dốc chuyển động nhanh dần đều với gia tốc 0,2 m/s². Cùng lúc đó, một ô tô đang chạy với vận tốc 20 m/s lên dốc, chuyển động chậm dần đều với gia tốc 0,4 m/s². Chọn chiều từ chân dốc lên đỉnh dốc là chiều dương. Xác định vị trí hai xe gặp nhau trên dốc. Biết dốc dài 570 m.</p><figure><img src=\"k10-c2-mr/h/t25_1340_1720.jpg\" width=\"620\" height=\"420\" style=\"width:5.02cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Chuyển động của ô tô: <span class=\"m\">v_{01}=20\\ \\text{m/s};\\ a_1=0{,}4\\ \\text{m/s}^2</span>."], ["b", "Chuyển động của xe đạp: <span class=\"m\">v_{02}=-2\\ \\text{m/s};\\ a_2=-0{,}2\\ \\text{m/s}^2</span>."], ["c", "Phương trình độ dời của ô tô, xe đạp: <span class=\"m\">d_1=20t+0{,}2t^2</span>; <span class=\"m\">d_2=-2t-0{,}1t^2</span>."], ["d", "Vị trí hai xe gặp nhau cách chân dốc 420 m."]], "tr": 25, "col": 0, "da": "S Đ S Đ", "lg": ["Ô tô lên dốc chậm dần: <span class=\"m\">v_{01}=20</span> m/s, <span class=\"m\">a_1=-0{,}4</span> m/s². Xe đạp xuống dốc nhanh dần theo chiều âm: <span class=\"m\">v_{02}=-2</span> m/s, <span class=\"m\">a_2=-0{,}2</span> m/s². <span class=\"m\">d_1=20t-0{,}2t^2</span>. Gốc ở chân dốc: <span class=\"m\">x_1=20t-0{,}2t^2</span>, <span class=\"m\">x_2=570-2t-0{,}1t^2</span>. Gặp nhau: <span class=\"m\">0{,}1t^2-22t+570=0</span> ⇒ <span class=\"m\">t=30</span> s ⇒ <span class=\"m\">x=420</span> m."]}, {"than": "<p>Một ô tô bắt đầu chuyển động thẳng nhanh dần đều. Trong giây thứ 6 xe đi được quãng đường 11 m.</p>", "lc": [], "ds": [["a", "Gia tốc của xe ô tô là 0,61 m/s²."], ["b", "Vận tốc của xe sau 10 s chuyển động là 6,1 m/s."], ["c", "Quãng đường xe đi được sau 10 s chuyển động là 100 m."], ["d", "Quãng đường xe đi trong 20 s đầu tiên là 400 m."]], "tr": 29, "col": 0, "da": "S S Đ Đ", "lg": ["Giây thứ 6: <span class=\"m\">5{,}5a=11</span> ⇒ <span class=\"m\">a=2</span> m/s². Sau 10 s: <span class=\"m\">v=20</span> m/s; <span class=\"m\">s_{10}=\\dfrac{1}{2}\\cdot 2\\cdot 10^2=100</span> m; <span class=\"m\">s_{20}=400</span> m."]}, {"than": "<p>Một xe ô tô chuyển động thẳng nhanh dần đều với vận tốc đầu 18 km/h. Trong giây thứ tư kể từ lúc bắt đầu chuyển động nhanh dần, xe đi được 12 m.</p>", "lc": [], "ds": [["a", "Quãng đường xe đi được trong giây thứ 10 là 50 m."], ["b", "Vật chuyển động nhanh dần đều trong 10 s, quãng đường đi được trong 4 s cuối là 84 m."], ["c", "Xe đạt vận tốc 36 km/h sau thời gian 2,5 s."], ["d", "Quãng đường xe đi sau 2,5 s là 18,5 m."]], "tr": 29, "col": 0, "da": "S Đ Đ S", "lg": ["<span class=\"m\">v_0=5</span> m/s, <span class=\"m\">a=2</span> m/s². Giây thứ 10: <span class=\"m\">5+\\dfrac{2}{2}(10^2-9^2)=24</span> m. 4 s cuối: <span class=\"m\">s_{10}-s_6=150-66=84</span> m. <span class=\"m\">v=10</span> m/s khi <span class=\"m\">t=\\dfrac{10-5}{2}=2{,}5</span> s; <span class=\"m\">s(2{,}5)=5\\cdot 2{,}5+2{,}5^2=18{,}75</span> m."]}, {"than": "<p>Một xe đang chuyển động với vận tốc 7,2 km/h thì tăng tốc. Sau 4 s, xe đi thêm được 40 m.</p>", "lc": [], "ds": [["a", "Gia tốc của xe là 4 m/s²."], ["b", "Vận tốc của xe sau 6 s là 26 m."], ["c", "Cuối giây thứ 6, xe tắt máy. Sau 13 s thì ngừng hẳn lại. Gia tốc của xe sau khi tắt máy là 2 m/s²."], ["d", "Quãng đường đi được cho đến khi dừng lại là 169 m."]], "tr": 29, "col": 0, "da": "Đ Đ Đ Đ", "lg": ["<span class=\"m\">v_0=2</span> m/s: <span class=\"m\">40=2\\cdot 4+\\dfrac{a}{2}\\cdot 4^2</span> ⇒ <span class=\"m\">a=4</span> m/s². <span class=\"m\">v_6=2+4\\cdot 6=26</span> m/s (ý b ghi nhầm đơn vị \"m\"). Tắt máy: <span class=\"m\">a'=\\dfrac{0-26}{13}=-2</span> m/s², độ lớn 2 m/s². Kể từ lúc tắt máy xe đi thêm <span class=\"m\">\\dfrac{26^2}{2\\cdot 2}=169</span> m (cả quá trình từ lúc tăng tốc: <span class=\"m\">84+169=253</span> m)."]}, {"than": "<p>Một chiếc xe đang chạy với tốc độ 36 km/h thì tài xế hãm phanh, xe chuyển động thẳng chậm dần đều rồi dừng lại sau 5 s.</p>", "lc": [], "ds": [["a", "Gia tốc của xe là 2 m/s²."], ["b", "Quãng đường xe chạy đến lúc dừng hẳn là 25."], ["c", "Quãng đường xe chạy sau 4 s là 20 m."], ["d", "Quãng đường xe chạy trong giây cuối cùng là 5 m."]], "tr": 29, "col": 0, "da": "Đ Đ S S", "lg": ["<span class=\"m\">v_0=10</span> m/s: <span class=\"m\">a=\\dfrac{0-10}{5}=-2</span> m/s², độ lớn 2 m/s². Quãng đường đến lúc dừng: <span class=\"m\">\\dfrac{10^2}{2\\cdot 2}=25</span> m. Sau 4 s: <span class=\"m\">10\\cdot 4-4^2=24</span> m. Giây cuối: <span class=\"m\">\\dfrac{1}{2}\\cdot 2\\cdot 1^2=1</span> m."]}], "III": [{"than": "<p>Sau khi khởi hành được 50 m, xe đạt vận tốc 5 m/s. Hỏi sau khi đi hết 50 m tiếp theo xe có vận tốc là bao nhiêu m/s? Biết xe chuyển động thẳng nhanh dần đều. (kết quả lấy 2 chữ số sau dấu phẩy thập phân)</p>", "lc": [], "ds": [], "tr": 26, "col": 0, "da": "7,07", "lg": ["<span class=\"m\">v_1^2=2a\\cdot 50</span>; <span class=\"m\">v_2^2=2a\\cdot 100=2v_1^2</span> ⇒ <span class=\"m\">v_2=5\\sqrt 2\\approx 7{,}07</span> m/s."]}, {"than": "<p>Xe chạy chậm dần lên một dốc có độ dài là S. Tốc độ ở chân dốc 54 km/h, ở đỉnh dốc là 36 km/h. Chọn gốc tọa độ tại chân dốc, chiều dương là chiều chuyển động. Sau khi lên được nửa dốc thì tốc độ xe bằng bao nhiêu cm/s? (kết quả lấy 0 chữ số sau dấu phẩy thập phân)</p>", "lc": [], "ds": [], "tr": 26, "col": 0, "da": "1275", "lg": ["<span class=\"m\">v_0=15</span> m/s, <span class=\"m\">v=10</span> m/s: <span class=\"m\">v_0^2-v^2=2|a|S</span>. Giữa dốc: <span class=\"m\">v'^2=\\dfrac{v_0^2+v^2}{2}=162{,}5</span> ⇒ <span class=\"m\">v'\\approx 12{,}75</span> m/s <span class=\"m\">=1275</span> cm/s."]}, {"than": "<p>Trong một quán ăn có hệ thống đưa thức ăn tự động bằng băng chuyền, một khách hàng đặt một món ăn qua hệ thống tự động. Sau đó, đĩa thức ăn được di chuyển từ khu vực bếp đến vị trí khách hàng cách nhau 5 m từ trạng thái nghỉ. Giả sử chuyển động của đĩa thức ăn là nhanh dần đều và biết tốc độ của đĩa thức ăn đến khách hàng là 2 m/s. Nếu trường hợp khách hàng đặt một li cocktail, vì chiều cao li và mặt đế của li nhỏ nên li sẽ bị đổ khi gia tốc của nó vượt quá 0,5 m/s². Tìm tốc độ tối đa mà li có thể đạt được để không bị đổ theo đơn vị cm/s? (kết quả lấy 0 chữ số sau dấu phẩy thập phân)</p>", "lc": [], "ds": [], "tr": 26, "col": 0, "da": "224", "lg": ["Với <span class=\"m\">a_{\\max}=0{,}5</span> m/s² trên quãng 5 m: <span class=\"m\">v=\\sqrt{2a_{\\max}s}=\\sqrt{2\\cdot 0{,}5\\cdot 5}=\\sqrt5\\approx 2{,}24</span> m/s <span class=\"m\">=224</span> cm/s."]}, {"than": "<p>Cho một máng nghiêng, lấy một viên bi lăn nhanh dần đều từ đỉnh một máng với không vận tốc ban đầu, bỏ qua ma sát giữa vật và máng, biết viên bi lăn với gia tốc 1 m/s². Biết vận tốc khi chạm đất 4 m/s. Tính chiều dài máng theo đơn vị cm? (kết quả lấy 0 chữ số sau dấu phẩy thập phân)</p><figure><img src=\"k10-c2-mr/h/t26_1185_1490.jpg\" width=\"665\" height=\"350\" style=\"width:5.38cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 26, "col": 0, "da": "800", "lg": ["<span class=\"m\">\\ell=\\dfrac{v^2}{2a}=\\dfrac{4^2}{2\\cdot 1}=8</span> m <span class=\"m\">=800</span> cm."]}, {"than": "<p>Một người đứng ở sân ga nhìn thấy đoàn tàu bắt đầu chuyển động. Người này nhìn thấy toa thứ nhất chạy qua trước mắt mình trong 10 s. Hãy tính thời gian toa thứ chín chạy qua người này, theo đơn vị phút? Giả sử chuyển động của tàu hỏa là nhanh dần đều và xem khoảng cách giữa các toa tàu là không đáng kể. (kết quả lấy 1 chữ số sau dấu phẩy thập phân)</p><figure><img src=\"k10-c2-mr/h/t26_1225_1895.jpg\" width=\"750\" height=\"380\" style=\"width:6.07cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 26, "col": 0, "da": "0,5", "lg": ["Mỗi toa dài <span class=\"m\">\\ell=\\dfrac{1}{2}a\\cdot 10^2</span>. Hết toa thứ <span class=\"m\">n</span> sau <span class=\"m\">t_n=10\\sqrt n</span> s: hết toa thứ chín sau <span class=\"m\">t_9=30</span> s <span class=\"m\">=0{,}5</span> phút. (Riêng toa thứ chín đi qua mất <span class=\"m\">10(\\sqrt9-\\sqrt8)\\approx 1{,}72</span> s.)"]}, {"than": "<p>Một ô tô chuyển động thẳng nhanh dần đều với vận tốc đầu là 18 km/h. Trong giây thứ 6 xe đi được quãng đường 21,5 m. Tính gia tốc của xe theo đơn vị cm/s²? (kết quả lấy 0 chữ số sau dấu phẩy thập phân)</p>", "lc": [], "ds": [], "tr": 30, "col": 0, "da": "300", "lg": ["<span class=\"m\">v_0=5</span> m/s. Giây thứ 6: <span class=\"m\">5+\\dfrac{a}{2}(6^2-5^2)=5+5{,}5a=21{,}5</span> ⇒ <span class=\"m\">a=3</span> m/s² <span class=\"m\">=300</span> cm/s²."]}, {"than": "<p>Một vật chuyển động thẳng nhanh dần đều từ trạng thái đứng yên và đi được đoạn đường s trong thời gian 4 s. Xác định thời gian vật đi được <span class=\"m\">\\dfrac{3}{4}</span> đoạn đường cuối, lấy đơn vị giây? (kết quả lấy 0 chữ số sau dấu phẩy thập phân)</p>", "lc": [], "ds": [], "tr": 30, "col": 0, "da": "2", "lg": ["<span class=\"m\">s\\sim t^2</span>: <span class=\"m\">\\dfrac14</span> đoạn đầu mất <span class=\"m\">4\\sqrt{\\tfrac14}=2</span> s ⇒ <span class=\"m\">\\dfrac34</span> đoạn cuối mất <span class=\"m\">4-2=2</span> s."]}, {"than": "<p>Một ô tô chuyển động biến đổi đều, trong giây cuối cùng (trước lúc dừng hẳn) đi được 0,5 m. Tính gia tốc của ô tô theo đơn vị m/s²? (kết quả lấy 0 chữ số sau dấu phẩy thập phân)</p>", "lc": [], "ds": [], "tr": 30, "col": 0, "da": "−1 (độ lớn 1)", "lg": ["Xét ngược thời gian, giây cuối giống giây đầu của chuyển động nhanh dần từ nghỉ: <span class=\"m\">0{,}5=\\dfrac{1}{2}|a|\\cdot 1^2</span> ⇒ <span class=\"m\">|a|=1</span> m/s²; chọn chiều dương là chiều chuyển động thì <span class=\"m\">a=-1</span> m/s²."]}, {"than": "<p>Một viên bi chuyển động thẳng nhanh dần đều không vận tốc đầu trên máng nghiêng và trong giây thứ năm nó đi được quãng đường bằng 1,8 m. Gia tốc của viên bi chuyển động trên máng nghiêng là bao nhiêu, theo đơn vị m/s²? (kết quả lấy 1 chữ số sau dấu phẩy thập phân)</p><figure><img src=\"k10-c2-mr/h/t30_1305_1180.jpg\" width=\"525\" height=\"280\" style=\"width:4.25cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 30, "col": 0, "da": "0,4", "lg": ["Giây thứ 5: <span class=\"m\">\\dfrac{a}{2}(5^2-4^2)=4{,}5a=1{,}8</span> ⇒ <span class=\"m\">a=0{,}4</span> m/s²."]}, {"than": "<p>Trong một chuyển động thẳng, đoạn đường của vật đi được trong 0,5 s liên tiếp sẽ tăng đều mỗi lần 1 m. Vậy gia tốc của chuyển động là bao nhiêu m/s²? (kết quả lấy 0 chữ số sau dấu phẩy thập phân)</p>", "lc": [], "ds": [], "tr": 30, "col": 0, "da": "4", "lg": ["<span class=\"m\">\\Delta s=aT^2</span> ⇒ <span class=\"m\">a=\\dfrac{1}{0{,}5^2}=4</span> m/s²."]}, {"than": "<p>Một vật đang đứng yên bắt đầu chuyển động nhanh dần đều với gia tốc 20 m/s² và đi được quãng đường dài 100 m mất thời gian là t (s). Gọi <span class=\"m\">S_1</span> là quãng đường vật đi được trong thời gian 0,5t (s) đầu tiên và <span class=\"m\">S_2</span> là quãng đường vật đi được trong thời gian 0,5t (s) còn lại. Tỉ số <span class=\"m\">S_2/S_1</span> bằng bao nhiêu? (kết quả lấy 0 chữ số sau dấu phẩy thập phân)</p>", "lc": [], "ds": [], "tr": 30, "col": 0, "da": "3", "lg": ["Từ nghỉ, hai nửa thời gian bằng nhau: <span class=\"m\">S_1:S_2=1:3</span> ⇒ <span class=\"m\">S_2/S_1=3</span>."]}]}, {"ten": "Đồ thị vận tốc – thời gian", "lt": "", "I": [{"than": "<p>Đồ thị vận tốc – thời gian nào sau đây mô tả chuyển động có độ lớn của gia tốc là lớn nhất (giả sử rằng tất cả các đồ thị có các vạch chia trên các trục Ot và Ov cùng tỉ lệ xích)?</p><figure><img src=\"k10-c2-mr/h/t31_270_165.jpg\" width=\"1520\" height=\"410\" style=\"width:12.30cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Đồ thị 1."], ["B", "Đồ thị 2."], ["C", "Đồ thị 3."], ["D", "Đồ thị 4."]], "ds": [], "tr": 30, "col": 4, "da": "D", "lg": ["Đồ thị 4 có đường <span class=\"m\">v(t)</span> dốc nhất (độ dốc của đồ thị <span class=\"m\">v-t</span> là gia tốc)."]}, {"than": "<p>Hình 7.2 mô tả đồ thị <span class=\"m\">(v-t)</span> của bốn xe ô tô A, B, C, D. Nhận định nào sau đây là đúng?</p><figure><img src=\"k10-c2-mr/h/t31_750_805.jpg\" width=\"625\" height=\"505\" style=\"width:5.06cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Xe C chuyển động đều, còn các xe còn lại là chuyển động biến đổi đều."], ["B", "Chỉ có xe C chuyển động đều và chuyển động của xe A là biến đổi đều."], ["C", "Xe A và B chuyển động biến đổi đều, xe C chuyển động đều."], ["D", "Xe D chuyển động biến đổi đều, xe C chuyển động đều."]], "ds": [], "tr": 31, "col": 1, "da": "C", "lg": ["Đồ thị A, B là đường thẳng xiên: biến đổi đều; C nằm ngang: chuyển động đều; D là đường cong: biến đổi nhưng không đều."]}, {"than": "<p>Đồ thị vận tốc theo thời gian của chuyển động thẳng như hình vẽ. Chuyển động thẳng nhanh dần đều là đoạn</p><figure><img src=\"k10-c2-mr/h/t31_805_1915.jpg\" width=\"515\" height=\"355\" style=\"width:4.17cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "MN."], ["B", "NO."], ["C", "OP."], ["D", "PQ."]], "ds": [], "tr": 31, "col": 4, "da": "D", "lg": ["Đoạn PQ: vận tốc tăng đều theo thời gian."]}, {"than": "<p>Quan sát đồ thị <span class=\"m\">(v-t)</span> trong hình vẽ của một vật đang chuyển động thẳng và cho biết trong khoảng thời gian nào gia tốc có độ lớn là lớn nhất?</p><figure><img src=\"k10-c2-mr/h/t31_820_2605.jpg\" width=\"515\" height=\"395\" style=\"width:4.17cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Trong khoảng thời gian từ 0 đến 1 s."], ["B", "Trong khoảng thời gian từ 1 đến 2 s."], ["C", "Trong khoảng thời gian từ 2 đến 3 s."], ["D", "Trong khoảng thời gian từ 3 đến 4 s."]], "ds": [], "tr": 31, "col": 2, "da": "A", "lg": ["Từ 0 đến 1 s vận tốc tăng 4 ô trong 1 s, độ dốc lớn nhất (từ 2 đến 3 s chỉ giảm 2 ô)."]}, {"than": "<p>Hình bên là đồ thị vận tốc – thời gian của hai vật chuyển động thẳng cùng hướng, xuất phát từ cùng một vị trí, gốc thời gian là lúc vật (1) bắt đầu chuyển động. Nhận xét <b>sai</b> là</p><figure><img src=\"k10-c2-mr/h/t32_815_610.jpg\" width=\"440\" height=\"335\" style=\"width:3.56cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Hai vật cùng chuyển động nhanh dần."], ["B", "Vật 1 bắt đầu chuyển động từ trạng thái nghỉ."], ["C", "Vật 2 chuyển động với gia tốc lớn hơn vật 1."], ["D", "Ở thời điểm <span class=\"m\">t_0</span>, vật 1 ở phía sau vật 2."]], "ds": [], "tr": 32, "col": 1, "da": "C", "lg": ["Đường (1) dốc hơn đường (2) nên vật 1 có gia tốc lớn hơn; nhận xét C sai. (Đến <span class=\"m\">t_0</span> diện tích dưới đường (2) lớn hơn nên vật 1 ở phía sau, D đúng.)"]}, {"than": "<p>Đồ thị vận tốc – thời gian của một vật chuyển động được biểu diễn như hình vẽ. Gọi <span class=\"m\">a_1</span>, <span class=\"m\">a_2</span>, <span class=\"m\">a_3</span> lần lượt là gia tốc của vật trong các giai đoạn tương ứng là từ t = 0 đến <span class=\"m\">t_1=20\\ \\text{s}</span>; từ <span class=\"m\">t_1=20\\ \\text{s}</span> đến <span class=\"m\">t_2=60\\ \\text{s}</span>; từ <span class=\"m\">t_2=60\\ \\text{s}</span> đến <span class=\"m\">t_3=80\\ \\text{s}</span>. Giá trị của <span class=\"m\">a_1</span>, <span class=\"m\">a_2</span>, <span class=\"m\">a_3</span> lần lượt là</p><figure><img src=\"k10-c2-mr/h/t32_760_1595.jpg\" width=\"495\" height=\"390\" style=\"width:4.01cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "−1 m/s²; 0; 2 m/s²."], ["B", "1 m/s²; 0; −2 m/s²."], ["C", "−1 m/s²; 2 m/s²; 0."], ["D", "1 m/s²; 0; 2 m/s²."]], "ds": [], "tr": 32, "col": 2, "da": "B", "lg": ["<span class=\"m\">a_1=\\dfrac{40-20}{20}=1</span> m/s²; <span class=\"m\">a_2=0</span>; <span class=\"m\">a_3=\\dfrac{0-40}{20}=-2</span> m/s²."]}, {"than": "<p>Một vật chuyển động thẳng biến đổi đều có đồ thị vận tốc v theo thời gian t như hình vẽ. Phương trình vận tốc của vật là</p><figure><img src=\"k10-c2-mr/h/t32_815_2370.jpg\" width=\"440\" height=\"335\" style=\"width:3.56cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "<span class=\"m\">v=15-t</span> (m/s)."], ["B", "<span class=\"m\">v=t+15</span> (m/s)."], ["C", "<span class=\"m\">v=10-15t</span> (m/s)."], ["D", "<span class=\"m\">v=10-5t</span> (m/s)."]], "ds": [], "tr": 32, "col": 4, "da": "A", "lg": ["Đường thẳng qua <span class=\"m\">(5\\ \\text{s};10\\ \\text{m/s})</span> và <span class=\"m\">(15\\ \\text{s};0)</span>: <span class=\"m\">a=-1</span> m/s², <span class=\"m\">v_0=15</span> m/s ⇒ <span class=\"m\">v=15-t</span>."]}, {"than": "<p>Đồ thị vận tốc – thời gian của một vật chuyển động như hình bên. Tỉ số về độ lớn gia tốc của vật trong thời gian OA và AB là</p><figure><img src=\"k10-c2-mr/h/t33_900_210.jpg\" width=\"460\" height=\"320\" style=\"width:3.72cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "1."], ["B", "<span class=\"m\">\\dfrac{1}{2}</span>."], ["C", "<span class=\"m\">\\dfrac{1}{3}</span>."], ["D", "3."]], "ds": [], "tr": 32, "col": 4, "da": "C", "lg": ["<span class=\"m\">|a_{OA}|=\\tan 30^\\circ</span>, <span class=\"m\">|a_{AB}|=\\tan 60^\\circ</span> (cùng tỉ lệ trục) ⇒ tỉ số <span class=\"m\">\\dfrac{\\tan 30^\\circ}{\\tan 60^\\circ}=\\dfrac13</span>."]}, {"than": "<p>Một chất điểm chuyển động thẳng đều, với đồ thị vận tốc – thời gian được cho như hình vẽ. Quãng đường mà chất điểm đi được trong khoảng thời gian từ 1 s đến 2 s là</p><figure><img src=\"k10-c2-mr/h/t33_1655_1525.jpg\" width=\"405\" height=\"335\" style=\"width:3.28cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "1 m."], ["B", "2 m."], ["C", "3 m."], ["D", "4 m."]], "ds": [], "tr": 33, "col": 4, "da": "C", "lg": ["<span class=\"m\">s=vt=3\\cdot 1=3</span> m."]}, {"than": "<p>Đồ thị vận tốc – thời gian của một vật chuyển động thẳng ở hình dưới. Quãng đường vật đã đi được sau 30 s là:</p><figure><img src=\"k10-c2-mr/h/t33_1420_2115.jpg\" width=\"565\" height=\"320\" style=\"width:4.57cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "200 m."], ["B", "250 m."], ["C", "300 m."], ["D", "350 m."]], "ds": [], "tr": 33, "col": 4, "da": "B", "lg": ["Quãng đường bằng diện tích dưới đồ thị: <span class=\"m\">\\dfrac12\\cdot 10\\cdot 10+10\\cdot 20=250</span> m."]}, {"than": "<p>Đồ thị vận tốc – thời gian của một tàu hỏa đang chuyển động thẳng có dạng như hình bên. Thời điểm t = 0 là lúc tàu đi qua sân ga. Vận tốc của tàu sau khi rời sân ga được 80 m là</p><figure><img src=\"k10-c2-mr/h/t33_1435_2460.jpg\" width=\"415\" height=\"420\" style=\"width:3.36cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "4 m/s."], ["B", "6 m/s."], ["C", "8 m/s."], ["D", "10 m/s."]], "ds": [], "tr": 33, "col": 4, "da": "B", "lg": ["Từ đồ thị: <span class=\"m\">v_0=2</span> m/s, <span class=\"m\">a=\\dfrac{12-2}{50}=0{,}2</span> m/s². <span class=\"m\">v^2=v_0^2+2ad=4+2\\cdot 0{,}2\\cdot 80=36</span> ⇒ <span class=\"m\">v=6</span> m/s."]}, {"than": "<p>Hình bên là đồ thị vận tốc – thời gian của hai vật chuyển động thẳng cùng hướng, xuất phát từ cùng một vị trí, gốc thời gian là lúc hai vật bắt đầu chuyển động. Nhận xét <b>sai</b> là</p><figure><img src=\"k10-c2-mr/h/t34_1490_440.jpg\" width=\"395\" height=\"355\" style=\"width:3.20cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Hai vật cùng chuyển động nhanh dần."], ["B", "Vật 1 bắt đầu chuyển động từ trạng thái nghỉ."], ["C", "Vật 2 chuyển động với gia tốc lớn hơn vật 1."], ["D", "Ở thời điểm <span class=\"m\">t_0</span>, vật 1 ở phía sau vật 2."]], "ds": [], "tr": 34, "col": 1, "da": "C", "lg": ["Đường (1) dốc hơn đường (2) nên vật 1 có gia tốc lớn hơn; nhận xét C sai."]}, {"than": "<p>Đồ thị vận tốc – thời gian của một vật chuyển động được biểu diễn như hình vẽ. Quãng đường vật đi được từ thời điểm t = 0 đến thời điểm t = 60 s là</p><figure><img src=\"k10-c2-mr/h/t34_1450_1206.jpg\" width=\"420\" height=\"339\" style=\"width:3.40cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "2,2 km."], ["B", "1,1 km."], ["C", "440 m."], ["D", "1,2 km."]], "ds": [], "tr": 34, "col": 4, "da": "A", "lg": ["Diện tích dưới đồ thị: <span class=\"m\">\\dfrac{(20+40)\\cdot 20}{2}+40\\cdot 40=600+1600=2200</span> m <span class=\"m\">=2{,}2</span> km."]}, {"than": "<p>Một vật chuyển động có đồ thị vận tốc – thời gian như hình vẽ. Quãng đường đi được trong giai đoạn chuyển động thẳng chậm dần đều là</p><figure><img src=\"k10-c2-mr/h/t34_1240_1765.jpg\" width=\"595\" height=\"320\" style=\"width:4.82cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "62,5 m."], ["B", "75 m."], ["C", "37,5 m."], ["D", "100 m."]], "ds": [], "tr": 34, "col": 4, "da": "C", "lg": ["Chậm dần đều từ 75 s đến 90 s: <span class=\"m\">s=\\dfrac12\\cdot 5\\cdot 15=37{,}5</span> m."]}, {"than": "<p>Đồ thị vận tốc – thời gian ở Hình 9.5 mô tả chuyển động của một chú chó con đang chạy trong một ngõ thẳng và hẹp. Tính quãng đường đi được và độ dịch chuyển của chú chó sau 10 s.</p><figure><img src=\"k10-c2-mr/h/t34_1210_2150.jpg\" width=\"750\" height=\"325\" style=\"width:6.07cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "S = 12 m, d = 9,5 m."], ["B", "S = 12,5 m, d = 9,5 m."], ["C", "S = 12 m, d = 9 m."], ["D", "S = 10 m, d = 9 m."]], "ds": [], "tr": 34, "col": 2, "da": "C", "lg": ["Diện tích các đoạn: 0–2 s: 2 m; 2–4 s: 4 m; 4–7 s: 4,5 m; 8–9 s: −0,5 m; 9–10 s: −1 m. Quãng đường <span class=\"m\">S=2+4+4{,}5+0{,}5+1=12</span> m; độ dịch chuyển <span class=\"m\">d=10{,}5-1{,}5=9</span> m."]}], "II": [{"than": "<p>Đồ thị mô tả sự thay đổi vận tốc theo thời gian trong chuyển động của một ô tô thể thao đang chạy thử về phía Bắc.</p><figure><img src=\"k10-c2-mr/h/t35_890_190.jpg\" width=\"920\" height=\"435\" style=\"width:7.45cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Ô tô bắt đầu chuyển động với vận tốc ban đầu là 20 m/s."], ["b", "Gia tốc của ô tô trong 4 s đầu là 5 m/s²."], ["c", "Gia tốc của ô tô từ giây thứ 20 đến giây thứ 28 là −2,5 m/s²."], ["d", "Quãng đường ô tô đi được sau 20 s đầu là 320 m."]], "tr": 35, "col": 0, "da": "S Đ Đ S", "lg": ["Từ đồ thị: <span class=\"m\">v_0=0</span>; 0–4 s: <span class=\"m\">a=\\dfrac{20}{4}=5</span> m/s²; 20–28 s: <span class=\"m\">a=\\dfrac{-20-0}{8}=-2{,}5</span> m/s². Quãng đường 20 s đầu bằng diện tích hình thang: <span class=\"m\">\\dfrac12\\cdot 4\\cdot 20+8\\cdot 20+\\dfrac12\\cdot 8\\cdot 20=280</span> m."]}, {"than": "<p>Từ các đồ thị trong hình 9.1. Nhận định sau đúng hay sai?</p><figure><img src=\"k10-c2-mr/h/t35_890_925.jpg\" width=\"950\" height=\"555\" style=\"width:7.69cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Chuyển động nhanh dần đều là: đồ thị a và b."], ["b", "Chuyển động chậm dần đều: đồ thị c."], ["c", "Đồ thị b: <span class=\"m\">v=v_0+at</span> (a &lt; 0)."], ["d", "Đồ thị c: <span class=\"m\">v=v_0+at</span> (a &gt; 0)."]], "tr": 35, "col": 0, "da": "Đ Đ S S", "lg": ["Đồ thị a, b: vận tốc tăng đều (NDĐ, <span class=\"m\">a>0</span>); đồ thị c: vận tốc giảm đều (CDĐ, <span class=\"m\">a&lt;0</span>)."]}, {"than": "<p>Chất điểm chuyển động có đồ thị vận tốc theo thời gian như hình.</p><figure><img src=\"k10-c2-mr/h/t35_905_1850.jpg\" width=\"935\" height=\"540\" style=\"width:7.57cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Quãng đường mà chất điểm đi được từ khi bắt đầu chuyển động cho tới 10 s là 43,75 m."], ["b", "Độ dịch chuyển của chất điểm từ khi bắt đầu chuyển động đến thời điểm 4 s là 10 m."], ["c", "Vận tốc trung bình của chất điểm trong 4 s đầu là 2 m/s."], ["d", "Tốc độ trung bình kể từ khi bắt đầu đi đến thời điểm 6 s là 3,1 m/s."]], "tr": 35, "col": 0, "da": "S Đ S S", "lg": ["Từ đồ thị: 0–3 s tăng từ 0 lên 4 m/s; 3–7 s đều 4 m/s; 7–10 s tăng từ 4 lên 6 m/s. Quãng đường 10 s: <span class=\"m\">6+16+15=37</span> m. Độ dịch chuyển 4 s đầu: <span class=\"m\">6+4=10</span> m ⇒ vận tốc trung bình <span class=\"m\">\\dfrac{10}{4}=2{,}5</span> m/s. 6 s đầu: <span class=\"m\">6+12=18</span> m ⇒ tốc độ trung bình 3 m/s."]}, {"than": "<p>Cho đồ thị (v – t) vẽ ở Hình bên. Biết mỗi cạnh của ô vuông nhỏ trên trục tung ứng với 2 m/s, trên trục hoành ứng với 1 s.</p><figure><img src=\"k10-c2-mr/h/t36_935_245.jpg\" width=\"705\" height=\"685\" style=\"width:5.71cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Vật chuyển thẳng chậm dần đều với vận tốc ban đầu là 4 m/s."], ["b", "Vận tốc của vật tại thời điểm <span class=\"m\">t_A</span> là 20 m/s."], ["c", "Độ dịch chuyển của chuyển động là 60 m."], ["d", "Giá trị của gia tốc là 2 m/s²."]], "tr": 36, "col": 0, "da": "S S Đ Đ", "lg": ["Mỗi ô: 2 m/s và 1 s. <span class=\"m\">v_0=4</span> m/s, sau 6 s đạt 16 m/s: <span class=\"m\">a=2</span> m/s², nhanh dần đều. <span class=\"m\">t_A=3</span> s ⇒ <span class=\"m\">v_A=4+2\\cdot 3=10</span> m/s. Độ dịch chuyển trong 6 s: <span class=\"m\">\\dfrac{(4+16)\\cdot 6}{2}=60</span> m."]}], "III": [{"than": "<p>Một xe đạp đang chuyển động với vận tốc 5 m/s thì hãm phanh chuyển động thẳng chậm dần đều. Hình 3.1 là đồ thị vận tốc – thời gian của xe đạp. Quãng đường xe đạp đi được từ lúc hãm phanh cho đến lúc dừng lại theo đơn vị m là bao nhiêu? (kết quả lấy đến 0 chữ số phần thập phân)</p><figure><img src=\"k10-c2-mr/h/t36_1025_1605.jpg\" width=\"675\" height=\"510\" style=\"width:5.46cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 36, "col": 0, "da": "25", "lg": ["Diện tích tam giác dưới đồ thị: <span class=\"m\">s=\\dfrac12\\cdot 5\\cdot 10=25</span> m."]}, {"than": "<p>Một người chạy xe máy theo một đường thẳng và có vận tốc theo thời gian được biểu diễn bởi đồ thị như hình. Xác định độ dịch chuyển của người này từ khi bắt đầu chạy đến thời điểm 4 s theo đơn vị cm? (kết quả lấy đến 0 chữ số phần thập phân)</p><figure><img src=\"k10-c2-mr/h/t36_1025_2140.jpg\" width=\"570\" height=\"445\" style=\"width:4.61cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 36, "col": 0, "da": "1100", "lg": ["Diện tích dưới đồ thị 0–4 s: <span class=\"m\">\\dfrac12\\cdot 2\\cdot 4+4\\cdot 1+\\dfrac{(4+2)\\cdot 1}{2}=4+4+3=11</span> m <span class=\"m\">=1100</span> cm."]}, {"than": "<p>Cho đồ thị của chuyển động như hình, tính gia tốc của vật trong 40 s kể từ khi bắt đầu chuyển động, lấy đơn vị m/s²? (kết quả lấy đến 0 chữ số phần thập phân)</p><figure><img src=\"k10-c2-mr/h/t37_1125_265.jpg\" width=\"690\" height=\"565\" style=\"width:5.59cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 37, "col": 0, "da": "2", "lg": ["<span class=\"m\">a=\\dfrac{120-40}{40}=2</span> m/s² (đọc trục vận tốc theo m/s; nếu trục ghi cm/s thì <span class=\"m\">a=2</span> cm/s² <span class=\"m\">=0{,}02</span> m/s²)."]}, {"than": "<p>Đồ thị vận tốc – thời gian trong hình bên dưới là của một xe bus và một xe máy đang chạy cùng chiều trên một đường thẳng. Xe bus đang đứng yên, bắt đầu chuyển động thì xe máy đi tới. Sau thời gian bao lâu thì xe bus đuổi kịp xe máy, lấy đơn vị giây? (kết quả lấy đến 0 chữ số phần thập phân)</p><figure><img src=\"k10-c2-mr/h/t37_1095_900.jpg\" width=\"770\" height=\"365\" style=\"width:6.23cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 37, "col": 0, "da": "10", "lg": ["Xe máy đều 8 m/s. Xe bus: 0–4 s tăng 0→8 m/s (đi 16 m), 4–8 s tăng 8→12 m/s (đi 40 m), sau đó đều 12 m/s. Đuổi kịp khi <span class=\"m\">56+12(t-8)=8t</span> ⇒ <span class=\"m\">t=10</span> s."]}, {"than": "<p>Một quả bóng bàn được bắn ra theo phương ngang với vận tốc đầu bằng không đến va chạm vào tường và bật lại trong khoảng thời gian rất ngắn. Hình bên là đồ thị (v – t) mô tả chuyển động của quả bóng trong 20 s đầu tiên. Tính quãng đường mà bóng bay được sau 20 s kể từ lúc bắt đầu chuyển động theo đơn vị dm? (kết quả lấy đến 0 chữ số phần thập phân)</p><figure><img src=\"k10-c2-mr/h/t37_1090_1320.jpg\" width=\"760\" height=\"520\" style=\"width:6.15cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 37, "col": 0, "da": "1125", "lg": ["0–5 s: <span class=\"m\">\\dfrac12\\cdot 5\\cdot 15=37{,}5</span> m; 5–20 s (bật ngược lại): <span class=\"m\">\\dfrac12\\cdot 15\\cdot 10=75</span> m. Quãng đường 112,5 m <span class=\"m\">=1125</span> dm."]}, {"than": "<p>Hai vật A và B chuyển động cùng chiều trên đường thẳng có đồ thị vận tốc – thời gian như hình vẽ. Biết ban đầu hai vật cách nhau 78 m. Hai vật có cùng vận tốc ở thời điểm nào, lấy đơn vị giây? (kết quả lấy đến 1 chữ số phần thập phân)</p><figure><img src=\"k10-c2-mr/h/t37_1105_1905.jpg\" width=\"655\" height=\"410\" style=\"width:5.30cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 37, "col": 0, "da": "13,3", "lg": ["<span class=\"m\">v_A=40-2t</span>, <span class=\"m\">v_B=t</span> ⇒ <span class=\"m\">40-2t=t</span> ⇒ <span class=\"m\">t\\approx 13{,}3</span> s (khoảng cách ban đầu 78 m không cần dùng)."]}]}], "dem": {"I": 43, "II": 11, "III": 17}, "word": "k10-c2-mr/word/Bai09_CD_thang_bien_doi_deu_Mo_rong.docx", "wordDa": "k10-c2-mr/word/Bai09_CD_thang_bien_doi_deu_Mo_rong_Dap_an.docx"}, "B10": {"ten": "Bài 10. Sự rơi tự do", "nhom": [{"ten": "", "lt": "<h3 class=\"lt-h\">SỰ RƠI TỰ DO</h3><h4>1. Sự rơi trong không khí</h4><figure><img src=\"k10-c2-mr/h/t37_1595_2830.jpg\" width=\"410\" height=\"245\" style=\"width:3.32cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>- Sự rơi của các vật trong không khí là chuyển động thường gặp. VD: quả táo rơi từ trên cây xuống; chiếc lá rơi;...</p><p>- Sự rơi của các vật khác nhau thì chuyển động khác nhau trong không khí.</p><p>- <i>Nguyên nhân:</i> do lực cản của không khí. Lực cản càng nhỏ so với trọng lực tác dụng lên vật thì vật sẽ rơi càng nhanh và ngược lại.</p><h4>2. Sự rơi tự do</h4><p>- Sự rơi tự do là sự rơi <b>chỉ</b> dưới tác dụng của trọng lực.</p><p>- Nếu vật rơi trong không khí mà độ lớn của lực cản không khí không đáng kể so với trọng lượng của vật thì cũng coi là rơi tự do.</p><figure><img src=\"k10-c2-mr/h/t38_1630_840.jpg\" width=\"345\" height=\"610\" style=\"width:2.79cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p><b>• Đặc điểm của chuyển động rơi tự do</b></p><p class=\"sub\">+ <i>Phương và chiều của chuyển động rơi tự do:</i> Phương thẳng đứng, chiều từ trên xuống dưới.</p><p class=\"sub\">+ <i>Tính chất của chuyển động rơi tự do:</i> là chuyển động thẳng nhanh dần đều.</p><p class=\"sub\">+ <i>Gia tốc rơi tự do</i></p><p class=\"sub\">✓ Ở cùng một nơi trên Trái Đất, mọi vật rơi tự do với cùng một gia tốc.</p><p class=\"sub\">✓ Kí hiệu: g</p><p class=\"sub\">✓ g phụ thuộc vào vĩ độ địa lí và độ cao.</p><p class=\"sub\">✓ Ở gần bề mặt Trái Đất, g = 9,8 m/s².</p><p><b>• Công thức rơi tự do</b></p><p>- Rơi tự do có các công thức của chuyển động nhanh dần đều không vận tốc ban đầu: <span class=\"m\">v_0=0</span>.</p><p>Chọn thời điểm ban đầu <span class=\"m\">t_0=0</span>.</p><p>⇒ Độ dịch chuyển, quãng đường đi được tại thời điểm t: <span class=\"m\">d=s=\\dfrac{1}{2}gt^2</span></p><p>- Vận tốc tức thời tại thời điểm t: <span class=\"m\">v_t=g.t</span></p><p>- Mối liên hệ giữa vận tốc, gia tốc và quãng đường đi được: <span class=\"m\">v^2=2.g.s</span></p>", "I": [{"than": "<p>Trường hợp nào dưới đây được xem là sự rơi tự do?</p><figure><img src=\"k10-c2-mr/h/t39_1340_255.jpg\" width=\"250\" height=\"195\" style=\"width:2.02cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Ném một hòn sỏi theo phương xiên góc."], ["B", "Ném một hòn sỏi theo phương nằm ngang."], ["C", "Ném một hòn sỏi lên cao."], ["D", "Thả một hòn sỏi rơi xuống."]], "ds": [], "tr": 38, "col": 2, "da": "D", "lg": ["Thả hòn sỏi (không vận tốc đầu), lực cản không đáng kể: rơi tự do."]}, {"than": "<p>Một vật rơi tự do thì chuyển động của vật</p>", "lc": [["A", "là chuyển động thẳng đều."], ["B", "là chuyển động thẳng nhanh dần đều."], ["C", "là chuyển động thẳng chậm dần đều."], ["D", "là chuyển động thẳng có gia tốc thay đổi theo thời gian."]], "ds": [], "tr": 39, "col": 1, "da": "B", "lg": ["Rơi tự do là chuyển động thẳng nhanh dần đều."]}, {"than": "<p>Điều nào sau đây là <b>không đúng</b> khi nói về chuyển động rơi tự do?</p>", "lc": [["A", "Sự rơi tự do là sự rơi của một vật chỉ dưới tác dụng của trọng lực."], ["B", "Các vật rơi tự do ở cùng một nơi trên Trái Đất và ở gần mặt đất đều có cùng một gia tốc."], ["C", "Trong quá trình rơi tự do, gia tốc của vật không đổi cả về hướng và độ lớn."], ["D", "Trong quá trình rơi tự do, gia tốc của vật không đổi cả về hướng và độ lớn."]], "ds": [], "tr": 39, "col": 1, "da": "D", "lg": ["Bản gốc in phương án D trùng C (lỗi in). A, B, C đều đúng; theo đề gốc phương án D là \"Chuyển động rơi tự do là chuyển động thẳng chậm dần đều\" nên D không đúng."]}, {"than": "<p>(SBT-KNTT) Chuyển động của vật nào dưới đây sẽ được coi là rơi tự do nếu được thả rơi?</p><figure><img src=\"k10-c2-mr/h/t39_140_1730.jpg\" width=\"1310\" height=\"295\" style=\"width:10.60cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Một chiếc khăn voan nhẹ."], ["B", "Một sợi chỉ."], ["C", "Một chiếc lá cây rụng."], ["D", "Một viên sỏi."]], "ds": [], "tr": 39, "col": 2, "da": "D", "lg": ["Viên sỏi nặng, nhỏ gọn: lực cản không khí không đáng kể so với trọng lực."]}, {"than": "<p>Chuyển động của vật rơi tự do <b>không</b> có tính chất nào sau đây?</p>", "lc": [["A", "Vận tốc của vật tăng đều theo thời gian."], ["B", "Gia tốc của vật tăng đều theo thời gian."], ["C", "Càng gần tới mặt đất vật rơi càng nhanh."], ["D", "Quãng đường vật đi được là hàm số bậc hai theo thời gian."]], "ds": [], "tr": 39, "col": 1, "da": "B", "lg": ["Gia tốc rơi tự do <span class=\"m\">g</span> không đổi."]}, {"than": "<p>Dạng đồ thị vận tốc – thời gian nào dưới đây mô tả chuyển động rơi tự do của vật ở gần mặt đất?</p><figure><img src=\"k10-c2-mr/h/t39_240_2630.jpg\" width=\"1160\" height=\"275\" style=\"width:9.39cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Đồ thị (1)"], ["B", "Đồ thị (2)"], ["C", "Đồ thị (3)"], ["D", "Đồ thị (4)"]], "ds": [], "tr": 39, "col": 4, "da": "C", "lg": ["Rơi tự do: <span class=\"m\">v=gt</span>, đồ thị là đường thẳng qua gốc tọa độ."]}, {"than": "<p>Chọn phát biểu <b>sai</b>.</p>", "lc": [["A", "Khi rơi tự do tốc độ của vật tăng dần."], ["B", "Vật rơi tự do khi lực cản không khí rất nhỏ so với trọng lực."], ["C", "Vận động viên nhảy dù từ máy bay xuống mặt đất sẽ rơi tự do."], ["D", "Rơi tự do có quỹ đạo là đường thẳng."]], "ds": [], "tr": 40, "col": 1, "da": "C", "lg": ["Vận động viên nhảy dù chịu lực cản không khí lớn (nhất là khi dù mở) nên không rơi tự do."]}, {"than": "<p>Đặc điểm nào dưới đây <b>không</b> phải là đặc điểm của chuyển động rơi tự do của các vật?</p>", "lc": [["A", "Chuyển động theo phương thẳng đứng, chiều từ trên xuống."], ["B", "Chuyển động thẳng nhanh dần đều."], ["C", "Ở cùng một nơi và gần mặt đất, mọi vật rơi tự do như nhau."], ["D", "Lúc t = 0 thì vận tốc của vật luôn khác 0."]], "ds": [], "tr": 40, "col": 1, "da": "D", "lg": ["Rơi tự do bắt đầu từ trạng thái nghỉ: lúc <span class=\"m\">t=0</span> thì <span class=\"m\">v=0</span>."]}, {"than": "<p>Nhận xét nào sau đây là <b>sai</b>?</p>", "lc": [["A", "Vectơ gia tốc rơi tự do có phương thẳng đứng, hướng xuống."], ["B", "Tại cùng một nơi trên Trái Đất gia tốc rơi tự do không đổi."], ["C", "Gia tốc rơi tự do thay đổi theo vĩ độ."], ["D", "Gia tốc rơi tự do là 9,81 m/s² tại mọi nơi."]], "ds": [], "tr": 40, "col": 1, "da": "D", "lg": ["<span class=\"m\">g</span> thay đổi theo vĩ độ và độ cao, không phải 9,81 m/s² ở mọi nơi."]}, {"than": "<p>Vật rơi tự do</p>", "lc": [["A", "khi từ nơi rất cao xuống mặt đất."], ["B", "khi hợp lực tác dụng vào vật hướng thẳng xuống mặt đất."], ["C", "chỉ dưới tác dụng của trọng lực."], ["D", "khi vật có khối lượng lớn rơi từ cao xuống mặt đất."]], "ds": [], "tr": 40, "col": 1, "da": "C", "lg": ["Rơi tự do là rơi chỉ dưới tác dụng của trọng lực."]}, {"than": "<p>(SBT-KNTT) Thả một hòn sỏi từ độ cao h xuống đất. Hòn sỏi rơi trong 2 s. Nếu thả hòn sỏi từ độ cao 2h xuống đất thì hòn sỏi sẽ rơi trong bao lâu?</p>", "lc": [["A", "2 s."], ["B", "<span class=\"m\">2\\sqrt{2}</span> s."], ["C", "4 s."], ["D", "<span class=\"m\">4\\sqrt{2}</span> s."]], "ds": [], "tr": 40, "col": 4, "da": "B", "lg": ["<span class=\"m\">t=\\sqrt{\\dfrac{2h}{g}}\\sim\\sqrt h</span>: độ cao gấp 2 thì thời gian gấp <span class=\"m\">\\sqrt2</span> ⇒ <span class=\"m\">2\\sqrt2</span> s."]}, {"than": "<p>(SBT-KNTT) Thả vật rơi tự do từ độ cao h xuống đất. Công thức tính vận tốc của vật khi chạm đất là:</p>", "lc": [["A", "<span class=\"m\">v=2\\sqrt{gh}</span>"], ["B", "<span class=\"m\">v=gh</span>"], ["C", "<span class=\"m\">v=2gh</span>"], ["D", "<span class=\"m\">v=\\sqrt{gh}</span>"]], "ds": [], "tr": 40, "col": 4, "da": "Không có", "lg": ["Công thức đúng là <span class=\"m\">v=\\sqrt{2gh}</span>, không có trong bốn phương án (bản gốc in sai; SBT-KNTT có phương án <span class=\"m\">v=\\sqrt{2gh}</span>). Giáo viên nên sửa một phương án thành <span class=\"m\">v=\\sqrt{2gh}</span>."]}, {"than": "<p>(SBT-KNTT) Một vật được thả rơi tự do từ độ cao 9,8 m xuống đất. Bỏ qua lực cản của không khí. Lấy gia tốc rơi tự do g = 9,8 m/s². Vận tốc v của vật trước khi chạm đất bằng</p>", "lc": [["A", "<span class=\"m\">9{,}8\\sqrt{2}</span> m/s"], ["B", "9,8 m/s."], ["C", "98 m/s."], ["D", "6,9 m/s."]], "ds": [], "tr": 40, "col": 4, "da": "A", "lg": ["<span class=\"m\">v=\\sqrt{2gh}=\\sqrt{2\\cdot 9{,}8\\cdot 9{,}8}=9{,}8\\sqrt2</span> m/s."]}, {"than": "<p>Một vật được thả rơi tự do từ đỉnh tháp, nó chạm đất trong thời gian 4 s. Lấy <span class=\"m\">g=10\\ \\text{m/s}^2</span>. Chiều cao của tháp là</p>", "lc": [["A", "80 m"], ["B", "40 m"], ["C", "20 m"], ["D", "160 m"]], "ds": [], "tr": 40, "col": 4, "da": "A", "lg": ["<span class=\"m\">h=\\dfrac12gt^2=\\dfrac12\\cdot 10\\cdot 4^2=80</span> m."]}, {"than": "<p>Một vật rơi tự do từ độ cao 20 m với đất. Lấy <span class=\"m\">g=10\\ \\text{m/s}^2</span>. Thời gian để vật chạm đất là:</p>", "lc": [["A", "1 s"], ["B", "<span class=\"m\">\\sqrt{2}</span> s"], ["C", "2 s"], ["D", "4 s"]], "ds": [], "tr": 40, "col": 4, "da": "C", "lg": ["<span class=\"m\">t=\\sqrt{\\dfrac{2h}{g}}=\\sqrt{\\dfrac{2\\cdot 20}{10}}=2</span> s."]}, {"than": "<p>Một hòn đá thả rơi tự do, vận tốc của nó sau khi rơi được một quãng đường h bằng v. Để vận tốc của vật khi chạm đất là 2v thì điểm thả rơi phải cách đất một khoảng H bằng</p>", "lc": [["A", "2h"], ["B", "4h"], ["C", "6h"], ["D", "8h"]], "ds": [], "tr": 41, "col": 4, "da": "B", "lg": ["<span class=\"m\">v^2=2gh</span>: vận tốc gấp 2 thì độ cao gấp 4 ⇒ <span class=\"m\">H=4h</span>."]}, {"than": "<p>Người ta thả một vật rơi tự do từ một tòa tháp thì sau 20 s vật chạm đất cho g = 10 m/s². Độ cao của vật sau khi vật thả được 4 s.</p>", "lc": [["A", "1920 m"], ["B", "1290 m"], ["C", "2910 m"], ["D", "1029 m"]], "ds": [], "tr": 41, "col": 4, "da": "A", "lg": ["Độ cao tháp <span class=\"m\">h=\\dfrac12\\cdot 10\\cdot 20^2=2000</span> m; sau 4 s vật rơi được <span class=\"m\">\\dfrac12\\cdot 10\\cdot 4^2=80</span> m ⇒ còn cách đất 1920 m."]}, {"than": "<p>Một vật được thả rơi từ độ cao 1280 m so với mặt đất. Lấy <span class=\"m\">g=10\\ \\text{m/s}^2</span>. Tìm thời gian để vật rơi đến đất?</p>", "lc": [["A", "15 s"], ["B", "16 s"], ["C", "51 s"], ["D", "15 s"]], "ds": [], "tr": 41, "col": 4, "da": "B", "lg": ["<span class=\"m\">t=\\sqrt{\\dfrac{2h}{g}}=\\sqrt{\\dfrac{2\\cdot 1280}{10}}=16</span> s."]}], "II": [{"than": "<p>Em nhận xét thế nào về các nhận định sau?</p>", "lc": [], "ds": [["a", "Sự rơi tự do là sự rơi chỉ dưới tác dụng của trọng lực."], ["b", "Rơi tự do có phương rơi thẳng đứng, chiều rơi từ trên xuống dưới."], ["c", "Ở cùng một nơi trên Trái Đất, mọi vật rơi tự do với gia tốc khác nhau."], ["d", "Gia tốc rơi tự do không phụ thuộc vào vĩ độ địa lí và độ cao."]], "tr": 41, "col": 0, "da": "Đ Đ S S", "lg": ["Ở cùng một nơi mọi vật rơi tự do với cùng gia tốc <span class=\"m\">g</span>; <span class=\"m\">g</span> phụ thuộc vĩ độ và độ cao."]}, {"than": "<p>Một vật rơi không vận tốc đầu từ đỉnh tòa nhà chung cư có độ cao 320 m xuống đất. Cho g = 10 m/s².</p>", "lc": [], "ds": [["a", "Vận tốc lúc vừa chạm đất là 80 m/s."], ["b", "Thời gian của vật rơi là 80 s."], ["c", "Quãng đường vật rơi được trong 6 s là 160 m."], ["d", "Quãng đường vật rơi được trong 6 s cuối cùng là 300 m."]], "tr": 41, "col": 0, "da": "Đ S S Đ", "lg": ["<span class=\"m\">v=\\sqrt{2gh}=80</span> m/s; <span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 320}{10}}=8</span> s; trong 6 s đầu rơi <span class=\"m\">\\dfrac12\\cdot 10\\cdot 6^2=180</span> m; 6 s cuối: <span class=\"m\">320-\\dfrac12\\cdot 10\\cdot 2^2=300</span> m."]}, {"than": "<p>Một người thả rơi một hòn bi từ trên cao xuống đất và đo được thời gian rơi là 3,1 s. Bỏ qua sức cản không khí. Lấy g = 10 m/s².</p>", "lc": [], "ds": [["a", "Độ cao của nơi thả hòn bi so với mặt đất là 48,05 m."], ["b", "Vận tốc lúc hòn bi chạm đất là 31,5 m/s."], ["c", "Quãng đường vật rơi được trong 2 giây là 20 m."], ["d", "Quãng đường vật rơi được trong giây thứ 2 là 15 m."]], "tr": 41, "col": 0, "da": "Đ S Đ Đ", "lg": ["<span class=\"m\">h=\\dfrac12\\cdot 10\\cdot 3{,}1^2=48{,}05</span> m; <span class=\"m\">v=gt=31</span> m/s; 2 s đầu: 20 m; giây thứ 2: <span class=\"m\">20-5=15</span> m."]}, {"than": "<p>Một quả bóng được thả rơi tự do từ độ cao 1,2 m. Sau khi chạm đất, quả bóng bật lên ở độ cao 0,80 m. Thời gian tiếp xúc giữa bóng và mặt đất là 0,16 s. Lấy g = 9,8 m/s². Bỏ qua sức cản của không khí.</p><figure><img src=\"k10-c2-mr/h/t41_1560_2200.jpg\" width=\"280\" height=\"490\" style=\"width:2.27cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Tốc độ của quả bóng ngay trước khi chạm đất là: 4,85 m/s."], ["b", "Thời gian quả bóng rơi chạm đất lần đầu là 0,459 s."], ["c", "Tốc độ của quả bóng ngay khi bắt đầu bật lên là 3,28 m/s."], ["d", "Độ lớn gia tốc của quả bóng khi nó tiếp xúc với mặt đất là 2,05 m/s²."]], "tr": 41, "col": 0, "da": "Đ S S S", "lg": ["<span class=\"m\">v_1=\\sqrt{2\\cdot 9{,}8\\cdot 1{,}2}\\approx 4{,}85</span> m/s; <span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 1{,}2}{9{,}8}}\\approx 0{,}495</span> s; <span class=\"m\">v_2=\\sqrt{2\\cdot 9{,}8\\cdot 0{,}8}\\approx 3{,}96</span> m/s; <span class=\"m\">a=\\dfrac{v_2-(-v_1)}{\\Delta t}=\\dfrac{3{,}96+4{,}85}{0{,}16}\\approx 55</span> m/s²."]}], "III": [{"than": "<p>Thả một hòn đá từ độ cao h = 5 m xuống mặt đất, hòn đá rơi trong 0,5 s. Nếu thả hòn đá từ độ cao h' xuống đất mất 1,5 s thì h' bằng bao nhiêu? (kết quả lấy đến 0 chữ số thập phân, theo đơn vị m)</p>", "lc": [], "ds": [], "tr": 42, "col": 0, "da": "45", "lg": ["<span class=\"m\">h\\sim t^2</span>: <span class=\"m\">h'=5\\cdot\\left(\\dfrac{1{,}5}{0{,}5}\\right)^2=45</span> m."]}, {"than": "<p>Ga-li-lê thả quả đạn hình cầu từ độ cao 56 m trên tháp nghiêng Pi-da xuống đất. Tính thời gian quả đạn rơi. Biết g = 9,81 m/s². (kết quả lấy đến 2 chữ số thập phân, theo đơn vị s)</p><figure><img src=\"k10-c2-mr/h/t42_1630_890.jpg\" width=\"410\" height=\"540\" style=\"width:3.32cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 42, "col": 0, "da": "3,38", "lg": ["<span class=\"m\">t=\\sqrt{\\dfrac{2h}{g}}=\\sqrt{\\dfrac{2\\cdot 56}{9{,}81}}\\approx 3{,}38</span> s."]}, {"than": "<p>Thả một hòn đá từ mép một vách núi dựng đứng xuống vực sâu. Sau 3,96 s từ lúc thả thì nghe thấy tiếng hòn đá chạm đáy vực sâu. Biết g = 9,8 m/s² và tốc độ truyền âm trong không khí là 330 m/s. Tìm chiều cao vách đá bờ vực đó. (kết quả lấy đến 0 chữ số thập phân, theo đơn vị m)</p>", "lc": [], "ds": [], "tr": 42, "col": 0, "da": "69", "lg": ["<span class=\"m\">t_1+\\dfrac{h}{330}=3{,}96</span> với <span class=\"m\">h=4{,}9t_1^2</span> ⇒ <span class=\"m\">t_1\\approx 3{,}75</span> s ⇒ <span class=\"m\">h\\approx 69</span> m."]}, {"than": "<p>Một trái banh được ném từ mặt đất thẳng đứng với vận tốc 20 m/s. Thời gian từ lúc ném banh đến lúc chạm đất là bao nhiêu? (kết quả lấy đến 0 chữ số thập phân, theo đơn vị s)</p>", "lc": [], "ds": [], "tr": 42, "col": 0, "da": "4", "lg": ["Lấy <span class=\"m\">g=10</span> m/s². Thời gian lên bằng thời gian xuống: <span class=\"m\">t=\\dfrac{2v_0}{g}=\\dfrac{2\\cdot 20}{10}=4</span> s."]}, {"than": "<p>Một vật rơi tự do từ độ cao h. Biết rằng trong giây cuối cùng vật rơi được 15 m. Độ cao nơi thả vật là bao nhiêu? (kết quả lấy đến 0 chữ số thập phân, theo đơn vị m)</p>", "lc": [], "ds": [], "tr": 42, "col": 0, "da": "20", "lg": ["Lấy <span class=\"m\">g=10</span> m/s². Giây cuối: <span class=\"m\">\\dfrac12gt^2-\\dfrac12g(t-1)^2=15</span> ⇒ <span class=\"m\">t=2</span> s ⇒ <span class=\"m\">h=\\dfrac12\\cdot 10\\cdot 2^2=20</span> m."]}, {"than": "<p>Một vật được thả rơi tự do, vận tốc của vật ngay trước khi chạm đất là 50 m/s. Cho <span class=\"m\">g=10\\ \\text{m/s}^2</span>. Độ cao của vật sau 3 s là bao nhiêu? (kết quả lấy đến 0 chữ số thập phân, theo đơn vị m)</p>", "lc": [], "ds": [], "tr": 42, "col": 0, "da": "80", "lg": ["<span class=\"m\">t=\\dfrac{v}{g}=5</span> s; <span class=\"m\">h=\\dfrac12\\cdot 10\\cdot 5^2=125</span> m. Sau 3 s rơi được 45 m ⇒ còn cách đất 80 m."]}]}], "dem": {"I": 18, "II": 4, "III": 6}, "word": "k10-c2-mr/word/Bai10_Su_roi_tu_do_Mo_rong.docx", "wordDa": "k10-c2-mr/word/Bai10_Su_roi_tu_do_Mo_rong_Dap_an.docx"}, "B11": {"ten": "Bài 11. Thực hành: Đo gia tốc rơi tự do", "nhom": [{"ten": "", "lt": "<h3 class=\"lt-h\">THỰC HÀNH ĐO GIA TỐC TRỌNG TRƯỜNG</h3><h4>1. Mục đích thực hành</h4><p>• Đo được gia tốc rơi tự do.</p><h4>2. Cách đo gia tốc trọng trường trong phòng thí nghiệm</h4><div class=\"mb\">g=\\dfrac{2S}{t^2}</div><p>Ta cần đo thời gian và quãng đường chuyển động của vật đó.</p><h4>3. Giới thiệu dụng cụ thí nghiệm</h4><figure><img src=\"k10-c2-mr/h/t43_1425_340.jpg\" width=\"380\" height=\"725\" style=\"width:3.08cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>- Bộ dụng cụ thí nghiệm đo gia tốc rơi tự do:</p><p class=\"sub\">+ Máng đứng có gắn dây dọi (1)</p><p class=\"sub\">+ Vật bằng thép hình trụ (2)</p><p class=\"sub\">+ Nam châm điện N, dùng giữ và thả trụ thép (3)</p><p class=\"sub\">+ Cổng quang điện E (4)</p><p class=\"sub\">+ Giá đỡ có đế ba chân, có vít chỉnh cân bằng và trụ thép (5)</p><p class=\"sub\">+ Đồng hồ đo thời gian hiện số (6)</p><p class=\"sub\">+ Công tắc kép (7)</p><h4>4. Thiết kế phương án và tiến hành thí nghiệm</h4><p>Thiết kế phương án thí nghiệm như bộ dụng cụ thí nghiệm đo gia tốc rơi tự do.</p><p><b>Tiến hành thí nghiệm</b></p><div class=\"tw\"><table><tr><td colspan=\"2\"><i>Thí nghiệm: Đo gia tốc rơi tự do</i></td></tr><tr><td><b>Bước 1</b></td><td>Bố trí thí nghiệm như hình.</td></tr><tr><td><b>Bước 2</b></td><td>Cắm nam châm điện vào ổ A và cổng quang điện vào ổ B ở mặt sau của đồng hồ đo thời gian hiện số.</td></tr><tr><td><b>Bước 3</b></td><td>Đặt MODE đồng hồ đo thời gian hiện số ở chế độ thích hợp A ↔ B.</td></tr><tr><td><b>Bước 4</b></td><td>Đặt trụ thép tại vị trí tiếp xúc với nam châm điện N và bị giữ lại ở đó.</td></tr><tr><td><b>Bước 5</b></td><td>Nhấn nút RESET của đồng hồ MC964 để chuyển các số hiển thị về giá trị ban đầu 0.000.</td></tr><tr><td><b>Bước 6</b></td><td>Nhấn nút của hộp công tắc kép để ngắt điện vào nam châm điện. Trụ thép rơi xuống và chuyển động đi qua cổng quang điện.</td></tr><tr><td><b>Bước 7</b></td><td>Ghi lại các giá trị thời gian hiển thị trên đồng hồ.</td></tr><tr><td><b>Bước 8</b></td><td>Dịch chuyển cổng quang điện ra xa dần nam châm điện, thực hiện lại các thao tác 3, 4, 5, 6 bốn lần nữa. Ghi lại thời gian t tương ứng với quãng đường s.</td></tr></table></div>", "I": [{"than": "<p>Chọn câu <b>đúng</b>, để đo gia tốc rơi tự do trong phòng thí nghiệm, ta cần:</p>", "lc": [["A", "Đo thời gian và quãng đường chuyển động của vật."], ["B", "Máy bắn tốc độ."], ["C", "Đồng hồ đo thời gian."], ["D", "Thước đo quãng đường."]], "ds": [], "tr": 43, "col": 1, "da": "A", "lg": ["<span class=\"m\">g=\\dfrac{2s}{t^2}</span>: cần đo thời gian và quãng đường chuyển động của vật."]}, {"than": "<p>Chọn câu <b>đúng</b>. Những dụng cụ chính để đo gia tốc rơi tự do của khối trụ gồm:</p>", "lc": [["A", "Đồng hồ đo thời gian hiện số, cổng quang điện, khối trụ, máng và thước thẳng."], ["B", "Đồng hồ đo thời gian hiện số, cổng quang điện, khối trụ, máng và thước kẹp."], ["C", "Đồng hồ đo thời gian hiện số, cần rung, khối trụ, máng và thước kẹp."], ["D", "Đồng hồ đo thời gian hiện số, cần rung, khối trụ, máng và thước thẳng."]], "ds": [], "tr": 43, "col": 1, "da": "A", "lg": ["Dụng cụ chính: đồng hồ đo thời gian hiện số, cổng quang điện, khối trụ (vật rơi), máng đứng và thước thẳng gắn trên máng."]}, {"than": "<p>Điền khuyết các từ khóa thích hợp vào chỗ trống: Khi cắm cổng quang điện vào ổ cắm A, B cần chú ý xoay đúng ……………, cắm thẳng ……………, không rung, lắc chân cắm.</p>", "lc": [["A", "máng, thước."], ["B", "khe định vị, thanh trụ."], ["C", "băng giấy, cần rung."], ["D", "khe định vị, giắc cắm."]], "ds": [], "tr": 44, "col": 2, "da": "D", "lg": ["Xoay đúng khe định vị, cắm thẳng giắc cắm."]}, {"than": "<p>Điền khuyết các từ khóa thích hợp vào chỗ trống: Để đo gia tốc rơi tự do trong phòng thí nghiệm, ta cần đo …………… và …………… chuyển động của vật đó.</p>", "lc": [["A", "vận tốc đầu, vận tốc cuối."], ["B", "thời gian đi qua một cổng quang điện, quãng đường."], ["C", "thời gian đi qua một cổng quang điện, vận tốc cuối."], ["D", "thời gian, quãng đường."]], "ds": [], "tr": 44, "col": 1, "da": "D", "lg": ["<span class=\"m\">g=\\dfrac{2s}{t^2}</span>: cần đo thời gian và quãng đường."]}, {"than": "<p>Điền khuyết các từ khóa thích hợp vào chỗ trống: Những dụng cụ chính để đo gia tốc rơi gồm: Đồng hồ đo thời gian hiện số và ……………, vật bằng thép hình trụ và ……………</p>", "lc": [["A", "máng, thước."], ["B", "cổng quang điện, thanh trụ."], ["C", "cổng quang điện, máng đứng có gắn thước."], ["D", "khe định vị, giắc cắm."]], "ds": [], "tr": 44, "col": 1, "da": "C", "lg": ["Đồng hồ đo thời gian hiện số và cổng quang điện, vật bằng thép hình trụ và máng đứng có gắn thước."]}, {"than": "<p>Sắp xếp theo đúng thứ tự các bước làm thí nghiệm đo gia tốc rơi tự do:</p><figure><img src=\"k10-c2-mr/h/t44_1465_1440.jpg\" width=\"610\" height=\"1070\" style=\"width:4.94cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p class=\"sub\">a. Đặt trụ thép tại vị trí tiếp xúc với nam châm điện N và bị giữ lại ở đó.</p><p class=\"sub\">b. Dịch chuyển cổng quang điện ra xa dần nam châm điện, thực hiện lại các thao tác 3, 4, 5, 6 bốn lần nữa. Ghi lại thời gian t tương ứng với quãng đường s.</p><p class=\"sub\">c. Bố trí thí nghiệm như hình.</p><p class=\"sub\">d. Nhấn nút RESET của đồng hồ MC964 để chuyển các số hiển thị về giá trị ban đầu 0.000.</p><p class=\"sub\">e. Nhấn nút của hộp công tắc kép để ngắt điện vào nam châm điện. Trụ thép rơi xuống và chuyển động đi qua cổng quang điện.</p><p class=\"sub\">f. Cắm nam châm điện vào ổ A và cổng quang điện vào ổ B ở mặt sau của đồng hồ đo thời gian hiện số.</p><p class=\"sub\">g. Ghi lại các giá trị thời gian hiển thị trên đồng hồ.</p><p class=\"sub\">h. Đặt MODE đồng hồ đo thời gian hiện số ở chế độ thích hợp A ↔ B.</p>", "lc": [["A", "c – d – e – g – b – f – h – a."], ["B", "c – f – h – a – d – e – g – b."], ["C", "c – f – e – g – b – h – a – d."], ["D", "c – f – g – b – h – a – d – e."]], "ds": [], "tr": 44, "col": 2, "da": "B", "lg": ["Theo bảng các bước: bố trí (c), cắm nam châm và cổng (f), đặt MODE (h), đặt trụ thép (a), RESET (d), thả vật (e), ghi thời gian (g), lặp lại (b)."]}, {"than": "<p>Sắp xếp theo đúng thứ tự các bước làm thí nghiệm đo gia tốc rơi tự do:</p><p class=\"sub\">a. Điều chỉnh giá đỡ thẳng đứng bằng các vít ở đế sao cho quả năng của dây dọi sẽ nằm ở tâm lỗ tròn. Thiết lập đồng hồ đo thời gian hiện số chế độ A ↔ B để đo thời gian từ lúc thả đến lúc vật chắn cổng quang điện.</p><p class=\"sub\">b. Lặp lại phép đo ít nhất 3 lần.</p><p class=\"sub\">c. Bố trí thí nghiệm như hình.</p><p class=\"sub\">d. Đặt vật rơi vào vị trí nam châm điện, dùng ê ke vuông ba chiều để xác định vị trí ban đầu của vật. Ấn nút RESET trên mặt đồng hồ để đưa chỉ thị số về 0.000. Nhấn công tắc điện để kích thích vật rơi và khởi động đồng hồ đo thời gian hiện số.</p><p class=\"sub\">e. Khi vật rơi và chắn các tia hồng ngoại của cổng quang điện, đồng hồ sẽ dừng. Đọc thời gian rơi trên đồng hồ và ghi số liệu vào bảng.</p>", "lc": [["A", "c – a – d – e – b."], ["B", "c – e – b – a – d."], ["C", "c – e – d – b – a."], ["D", "c – a – e – b – d."]], "ds": [], "tr": 44, "col": 4, "da": "A", "lg": ["Bố trí (c), chỉnh giá đỡ và đồng hồ (a), đặt vật, RESET, thả (d), đọc thời gian (e), lặp lại (b)."]}, {"than": "<p>Trước khi đo thời gian của một hoạt động ta thường ước lượng khoảng thời gian của hoạt động đó để</p>", "lc": [["A", "lựa chọn đồng hồ đo phù hợp."], ["B", "đặt mắt đúng cách."], ["C", "đọc kết quả đo chính xác."], ["D", "hiệu chỉnh đồng hồ đúng cách."]], "ds": [], "tr": 45, "col": 2, "da": "A", "lg": ["Ước lượng thời gian để chọn đồng hồ có giới hạn đo và độ chia nhỏ nhất phù hợp."]}, {"than": "<p>Cho các bước đo thời gian của một hoạt động gồm:</p><p class=\"sub\">(1) Đặt mắt nhìn đúng cách.</p><p class=\"sub\">(2) Ước lượng thời gian hoạt động cần đo để chọn đồng hồ thích hợp.</p><p class=\"sub\">(3) Hiệu chỉnh đồng hồ đo đúng cách.</p><p class=\"sub\">(4) Đọc, ghi kết quả đo đúng quy định.</p><p class=\"sub\">(5) Thực hiện phép đo thời gian.</p><p class=\"sub\">Thứ tự đúng các bước thực hiện để đo thời gian của một hoạt động là:</p>", "lc": [["A", "(1), (2), (3), (4), (5)"], ["B", "(3), (2), (5), (4), (1)"], ["C", "(2), (3), (1), (5), (4)"], ["D", "(2), (1), (3), (5), (4)."]], "ds": [], "tr": 45, "col": 2, "da": "C", "lg": ["Ước lượng và chọn đồng hồ (2), hiệu chỉnh (3), đặt mắt đúng cách (1), đo (5), đọc và ghi kết quả (4)."]}, {"than": "<p>Trong một bài thực hành, gia tốc RTD được tính theo công thức <span class=\"m\">g=\\dfrac{2h}{t^2}</span>. Sai số tỉ đối của phép đo trên tính theo công thức nào?</p>", "lc": [["A", "<span class=\"m\">\\dfrac{\\Delta g}{\\bar{g}}=\\dfrac{\\Delta h}{\\bar{h}}+2\\dfrac{\\Delta t}{\\bar{t}}</span>."], ["B", "<span class=\"m\">\\dfrac{\\Delta g}{\\bar{g}}=\\dfrac{\\Delta h}{\\bar{h}}+\\dfrac{\\Delta t}{\\bar{t}}</span>."], ["C", "<span class=\"m\">\\dfrac{\\Delta g}{\\bar{g}}=\\dfrac{\\Delta h}{\\bar{h}}-2\\dfrac{\\Delta t}{\\bar{t}}</span>."], ["D", "<span class=\"m\">\\dfrac{\\Delta g}{g}=\\dfrac{\\Delta h}{h}+2\\dfrac{\\Delta t}{t}</span>."]], "ds": [], "tr": 45, "col": 1, "da": "A", "lg": ["<span class=\"m\">g=\\dfrac{2h}{t^2}</span> ⇒ <span class=\"m\">\\dfrac{\\Delta g}{\\bar g}=\\dfrac{\\Delta h}{\\bar h}+2\\dfrac{\\Delta t}{\\bar t}</span> (sai số tỉ đối tính theo các giá trị trung bình)."]}, {"than": "<p>Một học sinh tiến hành đo gia tốc rơi tự do tại phòng thí nghiệm theo hướng dẫn của SGK VL 10. Phép đo gia tốc RTD học sinh này cho giá trị trung bình sau nhiều lần đo là <span class=\"m\">\\bar{g}=9{,}7166667\\ \\text{m/s}^2</span> với sai số tuyệt đối tương ứng là <span class=\"m\">\\Delta\\bar{g}=0{,}0681212\\ \\text{m/s}^2</span>. Kết quả của phép đo được biểu diễn bằng</p>", "lc": [["A", "<span class=\"m\">g=9{,}72\\pm0{,}068\\ \\text{m/s}^2</span>"], ["B", "<span class=\"m\">g=9{,}7\\pm0{,}1\\ \\text{m/s}^2</span>"], ["C", "<span class=\"m\">g=9{,}72\\pm0{,}07\\ \\text{m/s}^2</span>"], ["D", "<span class=\"m\">g=9{,}717\\pm0{,}068\\ \\text{m/s}^2</span>"]], "ds": [], "tr": 45, "col": 2, "da": "C", "lg": ["Sai số tuyệt đối làm tròn đến một chữ số có nghĩa: <span class=\"m\">\\Delta g\\approx 0{,}07</span> m/s²; giá trị trung bình lấy đến cùng hàng: <span class=\"m\">g=9{,}72\\pm 0{,}07</span> m/s²."]}, {"than": "<p>Để xác định gia tốc của một chuyển động thẳng biến đổi đều, một học sinh đã sử dụng đồng hồ bấm giờ và thước mét để xác định thời gian t và đo quãng đường L, sau đó xác định a bằng công thức <span class=\"m\">L=a\\dfrac{t^2}{2}</span>. Kết quả cho thấy <span class=\"m\">L=(2\\pm0{,}005)\\ \\text{m}</span>, <span class=\"m\">t=(4{,}2\\pm0{,}2)\\ \\text{s}</span>. Gia tốc a bằng:</p>", "lc": [["A", "<span class=\"m\">(0{,}23\\pm0{,}01)\\ \\text{m/s}^2</span>"], ["B", "<span class=\"m\">(0{,}23\\pm0{,}02)\\ \\text{m/s}^2</span>"], ["C", "<span class=\"m\">(0{,}23\\pm0{,}03)\\ \\text{m/s}^2</span>"], ["D", "<span class=\"m\">(0{,}23\\pm0{,}04)\\ \\text{m/s}^2</span>"]], "ds": [], "tr": 45, "col": 2, "da": "B", "lg": ["<span class=\"m\">\\bar a=\\dfrac{2L}{t^2}=\\dfrac{2\\cdot 2}{4{,}2^2}\\approx 0{,}227</span> m/s². <span class=\"m\">\\dfrac{\\Delta a}{\\bar a}=\\dfrac{0{,}005}{2}+2\\cdot\\dfrac{0{,}2}{4{,}2}\\approx 0{,}098</span> ⇒ <span class=\"m\">\\Delta a\\approx 0{,}02</span> m/s²."]}, {"than": "<p>Thả rơi tự do một vật từ đỉnh tháp thì thời gian vật chạm đất được xác định bằng <span class=\"m\">(2{,}0\\pm0{,}1)\\ \\text{s}</span>. Nếu lấy gia tốc trọng trường tại nơi thả vật chính xác bằng 10 m/s² thì chiều cao của tháp là</p><figure><img src=\"k10-c2-mr/h/t46_1590_310.jpg\" width=\"300\" height=\"405\" style=\"width:2.43cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "<span class=\"m\">(20\\pm0{,}1)\\ \\text{m}</span>"], ["B", "<span class=\"m\">(20\\pm0{,}5)\\ \\text{m}</span>"], ["C", "<span class=\"m\">(20\\pm1)\\ \\text{m}</span>"], ["D", "<span class=\"m\">(20\\pm2)\\ \\text{m}</span>"]], "ds": [], "tr": 46, "col": 4, "da": "D", "lg": ["<span class=\"m\">h=\\dfrac12gt^2=20</span> m; <span class=\"m\">\\dfrac{\\Delta h}{h}=2\\dfrac{\\Delta t}{t}=2\\cdot\\dfrac{0{,}1}{2}=0{,}1</span> ⇒ <span class=\"m\">\\Delta h=2</span> m."]}, {"than": "<p>Dùng một thước có chia độ đến milimét đo 5 lần khoảng cách d giữa hai điểm A và B đều cho cùng một giá trị là 1,345 m. Lấy sai số dụng cụ là một độ chia nhỏ nhất. Kết quả đo được viết là</p><figure><img src=\"k10-c2-mr/h/t46_1420_800.jpg\" width=\"475\" height=\"405\" style=\"width:3.85cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "<span class=\"m\">d=(1345\\pm2)</span> (mm)."], ["B", "<span class=\"m\">d=(1{,}345\\pm0{,}001)</span> (m)."], ["C", "<span class=\"m\">d=(1345\\pm3)</span> (mm)."], ["D", "<span class=\"m\">d=(1{,}345\\pm0{,}0005)</span> (m)."]], "ds": [], "tr": 46, "col": 2, "da": "B", "lg": ["Các lần đo như nhau nên sai số ngẫu nhiên bằng 0; sai số dụng cụ 1 mm <span class=\"m\">=0{,}001</span> m ⇒ <span class=\"m\">d=(1{,}345\\pm 0{,}001)</span> m."]}, {"than": "<p>Dùng một thước chia độ đến milimét để đo khoảng cách ℓ giữa hai điểm A, B và có kết quả đo là 600 mm. Lấy sai số dụng cụ là một độ chia nhỏ nhất. Cách ghi nào sau đây <b>không</b> đúng với số chữ số có nghĩa của phép đo?</p>", "lc": [["A", "<span class=\"m\">\\ell=(6{,}00\\pm0{,}01)</span> dm."], ["B", "<span class=\"m\">\\ell=(0{,}6\\pm0{,}001)</span> m."], ["C", "<span class=\"m\">\\ell=(60{,}0\\pm0{,}1)</span> cm."], ["D", "<span class=\"m\">\\ell=(600\\pm1)</span> mm."]], "ds": [], "tr": 46, "col": 2, "da": "B", "lg": ["Sai số 0,001 m thì giá trị phải ghi đến hàng phần nghìn: <span class=\"m\">0{,}600</span> m; cách ghi <span class=\"m\">0{,}6\\pm0{,}001</span> sai về chữ số có nghĩa."]}, {"than": "<p>Trong bài thực hành đo gia tốc RTD tại phòng thí nghiệm, một học sinh đo quãng đường vật rơi là <span class=\"m\">h=798\\pm1</span> (mm) và thời gian rơi là <span class=\"m\">t=0{,}404\\pm0{,}005</span> (s). Gia tốc RTD tại phòng thí nghiệm bằng: (Biết gia tốc RTD được tính theo công thức <span class=\"m\">g=2h/t^2</span>)</p>", "lc": [["A", "<span class=\"m\">g=9{,}78\\pm0{,}26\\ \\text{m/s}^2</span>."], ["B", "<span class=\"m\">g=9{,}87\\pm0{,}026\\ \\text{m/s}^2</span>."], ["C", "<span class=\"m\">g=9{,}78\\pm0{,}014\\ \\text{m/s}^2</span>."], ["D", "<span class=\"m\">g=9{,}87\\pm0{,}014\\ \\text{m/s}^2</span>."]], "ds": [], "tr": 46, "col": 2, "da": "A", "lg": ["<span class=\"m\">\\bar g=\\dfrac{2\\cdot 0{,}798}{0{,}404^2}\\approx 9{,}78</span> m/s². <span class=\"m\">\\dfrac{\\Delta g}{\\bar g}=\\dfrac{1}{798}+2\\cdot\\dfrac{0{,}005}{0{,}404}\\approx 0{,}026</span> ⇒ <span class=\"m\">\\Delta g\\approx 0{,}26</span> m/s²."]}], "II": [{"than": "<p>Khi tiến hành thí nghiệm đo gia tốc trọng trường, chọn các phát biểu đúng hoặc sai:</p>", "lc": [], "ds": [["a", "Để đo gia tốc rơi tự do trong phòng thí nghiệm, ta cần đo thể tích và quãng đường chuyển động của vật đó."], ["b", "Những dụng cụ chính để đo gia tốc rơi gồm: Đồng hồ đo thời gian hiện số và cổng quang điện, vật bằng thép hình trụ và máng đứng có gắn thước."], ["c", "Khi cắm cổng quang điện vào ổ cắm A, B cần chú ý xoay đúng khe định vị, cắm thẳng giắc cắm, không rung, lắc chân cắm."], ["d", "Cổng quang điện E để đo quãng đường rơi của vật."]], "tr": 46, "col": 0, "da": "S Đ Đ S", "lg": ["Cần đo thời gian và quãng đường (không phải thể tích). Cổng quang điện dùng để đo thời gian (cùng với đồng hồ hiện số), quãng đường đọc trên thước."]}, {"than": "<p>Khi tiến hành thí nghiệm đo gia tốc trọng trường <b>khi đo thời gian ta có bảng số liệu sau</b></p><div class=\"tw\"><table><tr><td><b>Quãng đường</b></td><td><b>Lần 1</b></td><td><b>Lần 2</b></td><td><b>Lần 3</b></td><td><b>Lần 4</b></td><td><b>Lần 5</b></td><td><b>Thời gian trung bình</b> <span class=\"m\">\\bar{t}</span></td></tr><tr><td>0,400</td><td>0,285</td><td>0,286</td><td>0,284</td><td>0,285</td><td>0,286</td><td></td></tr></table></div>", "lc": [], "ds": [["a", "Rơi tự do là chuyển động chậm dần đều."], ["b", "Sai số tỉ đối gia tốc rơi tự do được xác định theo biểu thức: <span class=\"m\">\\delta g=\\dfrac{\\overline{\\Delta g}}{\\bar{g}}.100\\%</span>."], ["c", "Giá trị trung bình của gia tốc rơi tự do 9,835 m/s²."], ["d", "Sai số tuyệt đối của gia tốc rơi tự do 0,81 m/s²."]], "tr": 46, "col": 0, "da": "S Đ Đ S", "lg": ["<span class=\"m\">\\bar t=\\dfrac{0{,}285+0{,}286+0{,}284+0{,}285+0{,}286}{5}=0{,}2852</span> s; <span class=\"m\">\\bar g=\\dfrac{2s}{\\bar t^2}=\\dfrac{2\\cdot 0{,}400}{0{,}2852^2}\\approx 9{,}835</span> m/s². <span class=\"m\">\\overline{\\Delta t}=0{,}00064</span> s ⇒ <span class=\"m\">\\Delta g\\approx\\bar g\\cdot 2\\dfrac{\\Delta t}{\\bar t}\\approx 0{,}04</span> m/s² (cộng thêm sai số dụng cụ 0,001 s thì khoảng 0,1 m/s²), không phải 0,81 m/s². Rơi tự do là nhanh dần đều."]}, {"than": "<p>Thả trụ thép rơi qua cổng quang điện trên máng đứng. Chọn phát biểu đúng hay sai?</p>", "lc": [], "ds": [["a", "Gia tốc rơi tự do của trụ thép theo công thức <span class=\"m\">g=\\dfrac{s}{t^2}</span>."], ["b", "Để xác định gia tốc rơi tự do của trụ thép cần đo đại lượng: quãng đường rơi của trụ thép và thời gian rơi."], ["c", "Để trụ thép rơi qua cổng quang điện cần đặt trụ thép tại vị trí tiếp xúc với nam châm điện và bị giữ lại ở đó. Nhấn nút của hộp công tắc kép để ngắt điện vào nam châm điện ⇒ trụ thép rơi xuống và chuyển động đi qua cổng quang điện."], ["d", "Đặt MODE đồng hồ đo thời gian hiện số ở chế độ thích hợp để đo được đại lượng cần đo. Ví dụ trường hợp này, đo thời gian từ lúc thả rơi đến lúc vật rơi hết quãng đường s nên ta đặt chế độ A + B."]], "tr": 47, "col": 0, "da": "S Đ Đ S", "lg": ["<span class=\"m\">s=\\dfrac12gt^2</span> ⇒ <span class=\"m\">g=\\dfrac{2s}{t^2}</span>. Đo thời gian từ lúc thả đến lúc vật chắn cổng quang điện thì đặt chế độ A ↔ B (không phải A + B)."]}], "III": []}], "dem": {"I": 16, "II": 3, "III": 0}, "word": "k10-c2-mr/word/Bai11_Thuc_hanh_do_g_Mo_rong.docx", "wordDa": "k10-c2-mr/word/Bai11_Thuc_hanh_do_g_Mo_rong_Dap_an.docx"}, "B12": {"ten": "Bài 12. Chuyển động ném", "nhom": [{"ten": "Chuyển động ném ngang", "lt": "<h3 class=\"lt-h\">CHUYỂN ĐỘNG NÉM NGANG</h3><p>- <b>Khái niệm:</b> Chuyển động ném ngang là chuyển động có vận tốc ban đầu theo phương nằm ngang và chuyển động dưới tác dụng của trọng lực.</p><p>- <b><i>Chọn hệ trục tọa độ Oxy:</i></b></p><p class=\"sub\">+ <i>Gốc O là vị trí ném vật;</i></p><p class=\"sub\">+ <i>Trục Ox theo hướng vận tốc đầu;</i></p><p class=\"sub\">+ <i>Trục Oy thẳng đứng hướng xuống.</i></p><p class=\"sub\">+ <i>Gốc thời gian lúc ném.</i></p><figure><img src=\"k10-c2-mr/h/t47_735_1860.jpg\" width=\"1140\" height=\"610\" style=\"width:9.23cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>- <b><i>Theo phương Ox:</i></b> <i><span class=\"m\">M_x</span> chuyển động thẳng đều với vận tốc <span class=\"m\">v_0</span>:</i> <span class=\"m\">a_x=0;\\ v_x=v_0;\\ d_x=v_x.t=v_0t</span></p><p>- <b><i>Theo phương Oy:</i></b> <i><span class=\"m\">M_y</span> chuyển động rơi tự do:</i> <span class=\"m\">a_y=g;\\ v_y=gt;\\ d_y=\\dfrac{1}{2}gt^2</span></p><p>- <i>Phương trình quỹ đạo của vật:</i> <span class=\"m\">d_y=\\dfrac{g}{2v_0^2}d_x^2</span> ⇒ <i>Quỹ đạo là một nhánh parabol</i></p><div class=\"tw\"><table><tr><td><b>- Thời gian vật chuyển động:</b></td><td><b>- Tầm bay xa:</b></td><td><b>- Vận tốc ở thời điểm t:</b></td></tr><tr><td><span class=\"m\">h=\\dfrac{1}{2}gt^2\\Rightarrow t=\\sqrt{\\dfrac{2h}{g}}</span></td><td><span class=\"m\">L=d_{x\\max}=v_0t=v_0\\sqrt{\\dfrac{2h}{g}}</span></td><td><span class=\"m\">v=\\sqrt{v_x^2+v_y^2}=\\sqrt{v_0^2+(g.t)^2}</span></td></tr><tr><td>➢ Thời gian vật chuyển động ném ngang bằng thời gian vật rơi tự do.<br>➢ Thời gian rơi của vật bị ném ngang chỉ phụ thuộc độ cao h của vật khi bị ném, không phụ thuộc vận tốc ném.<br>➢ Nếu từ cùng một độ cao, đồng thời ném ngang các vật khác nhau với các vận tốc khác nhau thì chúng đều rơi xuống đất cùng một lúc.</td><td>➢ Tầm xa của vật bị ném ngang phụ thuộc vào độ cao h và vận tốc ném.<br>➢ Nếu từ cùng một độ cao đồng thời ném các vật khác nhau với vận tốc khác nhau thì vật nào có vận tốc ném lớn hơn sẽ có tầm xa lớn hơn.<br>➢ Nếu các độ cao khác nhau ném ngang các vật với cùng vận tốc thì vật nào được ném ở độ cao lớn hơn sẽ có tầm xa lớn hơn.</td><td>➢ Khi chạm đất: <span class=\"m\">v_{cd}=\\sqrt{v_0^2+2gh}</span><br>➢ <span class=\"m\">\\vec{v}</span> hợp với phương ngang 1 góc α: <span class=\"m\">\\tan\\alpha=\\dfrac{v_y}{v_x}</span></td></tr></table></div>", "I": [{"than": "<p>Bi A có trọng lượng lớn gấp đôi bi B. Cùng một lúc tại một mái nhà ở cùng độ cao, bi A được thả còn bi B được ném theo phương ngang với tốc độ lớn. Bỏ qua sức cản không khí. Hãy cho biết câu nào sau đây đúng?</p>", "lc": [["A", "A chạm đất trước."], ["B", "A chạm đất sau B."], ["C", "Cả hai chạm đất cùng lúc."], ["D", "Chưa đủ thông tin trả lời."]], "ds": [], "tr": 48, "col": 2, "da": "C", "lg": ["Thời gian rơi chỉ phụ thuộc độ cao <span class=\"m\">t=\\sqrt{\\dfrac{2h}{g}}</span>, không phụ thuộc khối lượng và vận tốc ném ngang."]}, {"than": "<p>(SBT-KNTT) Một quả bóng đặt trên mặt bàn được truyền một vận tốc theo phương nằm ngang. Hình nào dưới đây mô tả <b>đúng</b> quỹ đạo của quả bóng khi rời khỏi mặt bàn?</p><figure><img src=\"k10-c2-mr/h/t48_195_2370.jpg\" width=\"1755\" height=\"395\" style=\"width:14.21cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Hình A."], ["B", "Hình B."], ["C", "Hình C."], ["D", "Hình D."]], "ds": [], "tr": 48, "col": 4, "da": "B", "lg": ["Rời mép bàn, quả bóng chuyển động theo nhánh parabol bắt đầu từ mép bàn, tiếp tuyến ban đầu nằm ngang."]}, {"than": "<p>Một vật được ném theo phương ngang với vận tốc <span class=\"m\">\\vec{v_0}</span> từ độ cao h so với mặt đất. Chọn hệ trục toạ độ Oxy sao cho gốc O trùng với vị trí ném, Ox theo phương vận tốc ban đầu, Oy hướng thẳng đứng xuống dưới, gốc thời gian là lúc ném. Độ lớn vận tốc của vật tại thời điểm t xác định bằng biểu thức:</p>", "lc": [["A", "<span class=\"m\">v=v_0+gt</span>."], ["B", "<span class=\"m\">v=\\sqrt{v_0^2+g^2t^2}</span>."], ["C", "<span class=\"m\">v=\\sqrt{v_0+gt}</span>."], ["D", "<span class=\"m\">v=gt</span>."]], "ds": [], "tr": 48, "col": 4, "da": "B", "lg": ["<span class=\"m\">v_x=v_0</span>, <span class=\"m\">v_y=gt</span> ⇒ <span class=\"m\">v=\\sqrt{v_0^2+g^2t^2}</span>."]}, {"than": "<p>Khi vật được ném theo phương ngang thì trên phương Ox</p>", "lc": [["A", "vật chuyển động thẳng đều."], ["B", "vật chuyển động nhanh dần đều."], ["C", "vật có gia tốc a = g."], ["D", "phương trình chuyển động <span class=\"m\">x=v_0t+\\dfrac{gt^2}{2}</span>."]], "ds": [], "tr": 49, "col": 1, "da": "A", "lg": ["Trên Ox không có lực tác dụng (bỏ qua lực cản): chuyển động thẳng đều với <span class=\"m\">v_x=v_0</span>."]}, {"than": "<p>Một vật ném theo phương ngang. Khi đang chuyển động sẽ chịu tác dụng của các lực.</p>", "lc": [["A", "lực ném và trọng lực."], ["B", "lực cản của không khí và trọng lực."], ["C", "lực ném và lực ma sát."], ["D", "trọng lực và phản lực đàn hồi."]], "ds": [], "tr": 49, "col": 2, "da": "B", "lg": ["Sau khi rời tay không còn \"lực ném\"; vật chịu trọng lực và lực cản của không khí."]}, {"than": "<p>Đối với hai vật bị ném ngang thì vật nào có</p>", "lc": [["A", "vận tốc ban đầu lớn hơn và khối lượng lớn hơn thì bay xa hơn."], ["B", "khối lượng lớn hơn thì bay xa hơn."], ["C", "khối lượng nhỏ hơn thì bay xa hơn."], ["D", "vận tốc ban đầu và độ cao ban đầu lớn hơn thì bay xa hơn."]], "ds": [], "tr": 49, "col": 1, "da": "D", "lg": ["<span class=\"m\">L=v_0\\sqrt{\\dfrac{2h}{g}}</span>: phụ thuộc vận tốc ban đầu và độ cao, không phụ thuộc khối lượng."]}, {"than": "<p>Một vật ném theo phương ngang. Khi đang chuyển động sẽ chịu tác dụng của các lực:</p>", "lc": [["A", "lực ném và trọng lực."], ["B", "lực cản của không khí và trọng lực."], ["C", "lực ném và lực ma sát."], ["D", "trọng lực và phản lực đàn hồi."]], "ds": [], "tr": 49, "col": 2, "da": "B", "lg": ["Sau khi rời tay không còn \"lực ném\"; vật chịu trọng lực và lực cản của không khí."]}, {"than": "<p>Vật chuyển động ném ngang từ độ cao h và vận tốc ban đầu <span class=\"m\">v_0</span>. Thời gian rơi đến khi chạm đất là</p>", "lc": [["A", "<span class=\"m\">t=\\sqrt{\\dfrac{2h}{g}}</span>."], ["B", "<span class=\"m\">t=\\sqrt{\\dfrac{h}{2g}}</span>."], ["C", "<span class=\"m\">t=\\sqrt{\\dfrac{h}{g}}</span>."], ["D", "<span class=\"m\">t=\\sqrt{2hg}</span>."]], "ds": [], "tr": 49, "col": 4, "da": "A", "lg": ["<span class=\"m\">h=\\dfrac12gt^2</span> ⇒ <span class=\"m\">t=\\sqrt{\\dfrac{2h}{g}}</span>."]}, {"than": "<p>Trong chuyển động ném ngang, gia tốc của vật tại một vị trí bất kì luôn có hướng theo</p>", "lc": [["A", "phương ngang, cùng chiều chuyển động."], ["B", "phương ngang, ngược chiều chuyển động."], ["C", "phương thẳng đứng, chiều từ trên xuống."], ["D", "phương thẳng đứng, chiều từ dưới lên."]], "ds": [], "tr": 49, "col": 1, "da": "C", "lg": ["Gia tốc của vật ném ngang là <span class=\"m\">\\vec g</span>: phương thẳng đứng, chiều từ trên xuống."]}, {"than": "<p>Một vật có khối lượng M, được ném ngang với vận tốc ban đầu V ở độ cao h. Bỏ qua sức cản không khí. Tầm bay xa của vật phụ thuộc vào</p>", "lc": [["A", "M và V."], ["B", "M và h."], ["C", "V và h."], ["D", "M, V và h."]], "ds": [], "tr": 49, "col": 4, "da": "C", "lg": ["<span class=\"m\">L=V\\sqrt{\\dfrac{2h}{g}}</span>: phụ thuộc V và h."]}, {"than": "<p>Để tăng tầm xa của vật ném theo phương ngang với sức cản không khí không đáng kể thì biện pháp nào sau đây có hiệu quả nhất?</p>", "lc": [["A", "Giảm khối lượng vật ném."], ["B", "Tăng độ cao điểm ném."], ["C", "Giảm độ cao điểm ném."], ["D", "Tăng vận tốc ném."]], "ds": [], "tr": 49, "col": 2, "da": "D", "lg": ["<span class=\"m\">L=v_0\\sqrt{\\dfrac{2h}{g}}</span>: L tỉ lệ thuận với <span class=\"m\">v_0</span> nhưng chỉ tỉ lệ với <span class=\"m\">\\sqrt h</span>, nên tăng vận tốc ném hiệu quả nhất."]}, {"than": "<p>Từ một độ cao, ném đồng thời hai vật theo phương ngang với vận tốc khác nhau <span class=\"m\">v_1>v_2</span>.</p>", "lc": [["A", "Vật 1 sẽ rơi chạm đất trước vật 2."], ["B", "Vật 1 sẽ rơi xa hơn vật 2."], ["C", "Cả hai vật chạm đất cùng lúc."], ["D", "Câu B và C đều đúng."]], "ds": [], "tr": 49, "col": 2, "da": "D", "lg": ["Cùng độ cao nên chạm đất cùng lúc; <span class=\"m\">v_1>v_2</span> nên vật 1 rơi xa hơn."]}, {"than": "<p>(SBT-KNTT) Một vật được ném từ độ cao H với vận tốc ban đầu <span class=\"m\">v_0</span> theo phương nằm ngang. Nếu bỏ qua sức cản của không khí thì tầm xa L</p>", "lc": [["A", "tăng 4 lần khi <span class=\"m\">v_0</span> tăng 2 lần."], ["B", "tăng 2 lần khi H tăng 2 lần."], ["C", "giảm 2 lần khi H giảm 4 lần."], ["D", "giảm 2 lần khi <span class=\"m\">v_0</span> giảm 4 lần."]], "ds": [], "tr": 50, "col": 2, "da": "C", "lg": ["<span class=\"m\">L=v_0\\sqrt{\\dfrac{2H}{g}}\\sim v_0\\sqrt H</span>: H giảm 4 lần thì L giảm 2 lần."]}, {"than": "<p>Một viên bi được ném theo phương ngang với vận tốc 2 m/s từ độ cao 5 m so với mặt đất. Lấy g = 10 m/s². Tầm ném xa của viên bi là</p>", "lc": [["A", "2,82 m."], ["B", "1 m."], ["C", "1,41 m."], ["D", "2 m."]], "ds": [], "tr": 50, "col": 4, "da": "D", "lg": ["<span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 5}{10}}=1</span> s ⇒ <span class=\"m\">L=v_0t=2</span> m."]}, {"than": "<p>Tầm xa L của vật chuyển động ném ngang từ độ cao h và vận tốc ban đầu <span class=\"m\">v_0</span> được xác định bằng biểu thức</p>", "lc": [["A", "<span class=\"m\">L=x_{\\max}=v_0\\sqrt{2gh}</span>."], ["B", "<span class=\"m\">L=x_{\\max}=v_0\\sqrt{\\dfrac{h}{g}}</span>."], ["C", "<span class=\"m\">L=x_{\\max}=v_0\\sqrt{\\dfrac{2h}{g}}</span>."], ["D", "<span class=\"m\">L=x_{\\max}=v_0\\dfrac{h}{2g}</span>."]], "ds": [], "tr": 50, "col": 4, "da": "C", "lg": ["<span class=\"m\">L=v_0t=v_0\\sqrt{\\dfrac{2h}{g}}</span>."]}, {"than": "<p>Một vật được ném theo phương ngang với vận tốc ban đầu <span class=\"m\">v_0=30\\ \\text{m/s}</span> ở độ cao h = 80 m so với mặt đất. Bỏ qua sức cản của không khí lấy <span class=\"m\">g=10\\ \\text{m/s}^2</span>. Phương trình quỹ đạo có dạng</p>", "lc": [["A", "<span class=\"m\">y=\\dfrac{x^2}{90}</span>."], ["B", "<span class=\"m\">y=\\dfrac{x^2}{120}</span>."], ["C", "<span class=\"m\">y=\\dfrac{x^2}{180}</span>."], ["D", "<span class=\"m\">y=\\dfrac{x^2}{150}</span>."]], "ds": [], "tr": 50, "col": 4, "da": "C", "lg": ["<span class=\"m\">y=\\dfrac{g}{2v_0^2}x^2=\\dfrac{10}{2\\cdot 30^2}x^2=\\dfrac{x^2}{180}</span>."]}, {"than": "<p>Một máy bay, bay với vận tốc không đổi <span class=\"m\">v_0</span> theo phương ngang ở độ cao h so với mặt đất và thả rơi một vật. Khi h = 1500 m. Xác định <span class=\"m\">v_0</span> để quãng đường mà vật đi được theo phương ngang kể từ lúc thả ra cho đến khi chạm đất bằng 2000 m. Lấy g = 9,8 m/s².</p>", "lc": [["A", "<span class=\"m\">v_0=114{,}33</span> m/s"], ["B", "200 m/s."], ["C", "113,4 m/s."], ["D", "318 m/s."]], "ds": [], "tr": 50, "col": 4, "da": "A", "lg": ["<span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 1500}{9{,}8}}\\approx 17{,}5</span> s ⇒ <span class=\"m\">v_0=\\dfrac{2000}{t}\\approx 114{,}3</span> m/s."]}, {"than": "<p>Phương trình quỹ đạo của một vật được ném theo phương nằm ngang có dạng <span class=\"m\">y=\\dfrac{x^2}{10}</span>. Biết g = 9,8 m/s². Vận tốc ban đầu của vật là</p>", "lc": [["A", "7 m/s."], ["B", "5 m/s."], ["C", "2,5 m/s."], ["D", "4,9 m/s."]], "ds": [], "tr": 50, "col": 4, "da": "A", "lg": ["<span class=\"m\">\\dfrac{g}{2v_0^2}=\\dfrac{1}{10}</span> ⇒ <span class=\"m\">v_0^2=5g=49</span> ⇒ <span class=\"m\">v_0=7</span> m/s."]}], "II": [{"than": "<p>Một người đang chơi ở đỉnh tòa nhà cầm một vật có khối lượng m ném theo phương ngang với tốc độ ban đầu là 20 m/s xuống đất, bỏ qua lực cản của không khí. Cho <span class=\"m\">g=10\\ \\text{m/s}^2</span>. Nếu chọn gốc O là vị trí ném vật; trục Ox theo hướng vận tốc đầu; trục Oy thẳng đứng hướng xuống, gốc thời gian lúc ném.</p>", "lc": [], "ds": [["a", "Độ lớn vận tốc của vật tăng dần theo thời gian."], ["b", "Tầm ném xa tỉ lệ với vận tốc ban đầu và độ cao ban đầu."], ["c", "Chuyển động của vật xét trên trục Ox có phương trình: x = 20t."], ["d", "Phương trình quỹ đạo của vật có dạng <span class=\"m\">y=-\\dfrac{x^2}{80}</span>."]], "tr": 50, "col": 0, "da": "Đ S Đ S", "lg": ["<span class=\"m\">v=\\sqrt{v_0^2+g^2t^2}</span> tăng theo t. <span class=\"m\">L=v_0\\sqrt{\\dfrac{2h}{g}}</span> tỉ lệ với <span class=\"m\">v_0</span> và với <span class=\"m\">\\sqrt h</span> (không tỉ lệ với h). <span class=\"m\">x=20t</span>; <span class=\"m\">y=\\dfrac{g}{2v_0^2}x^2=\\dfrac{x^2}{80}</span> (Oy hướng xuống nên y dương, không có dấu trừ)."]}, {"than": "<p>Quả bóng A được thả rơi tự do, cùng lúc ném quả bóng B với tốc độ 15 m/s theo phương ngang cùng độ cao h = 10 m. Cho <span class=\"m\">g=10\\ \\text{m/s}^2</span> thì:</p>", "lc": [], "ds": [["a", "Thời gian rơi theo phương thẳng đứng của quả bóng A nhỏ hơn thời gian của quả bóng B."], ["b", "Tốc độ chạm đất của hai quả bóng là như nhau."], ["c", "Thời gian rơi của quả bóng B là 1 s."], ["d", "Tầm ném xa của quả bóng B là <span class=\"m\">L=15\\sqrt{2}</span> m."]], "tr": 51, "col": 0, "da": "S S S Đ", "lg": ["Thời gian rơi như nhau: <span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 10}{10}}=\\sqrt2\\approx 1{,}41</span> s. Bóng B có thêm vận tốc ngang nên chạm đất nhanh hơn A. <span class=\"m\">L=15\\sqrt2\\approx 21{,}2</span> m."]}, {"than": "<p>Một chiếc máy bay muốn thả hàng tiếp tế cho những người leo núi đang bị cô lập. Máy bay đang bay ở độ cao 235 m so với vị trí đứng của những người leo núi với tốc độ 250 km/h theo phương ngang. Lấy g = 9,8 m/s² và bỏ qua lực cản của không khí.</p><figure><img src=\"k10-c2-mr/h/t51_1240_640.jpg\" width=\"770\" height=\"510\" style=\"width:6.23cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Người quan sát đứng trên núi nhìn thấy quỹ đạo của gói hàng là một phần của Parabol."], ["b", "Người quan sát đứng trên máy bay nhìn thấy quỹ đạo của vật là một đường thẳng đứng."], ["c", "Thời gian rơi của gói hàng là 4,9 s."], ["d", "Để người nhận được hàng tiếp tế, máy bay phải thả hàng cách người một khoảng 480,9 m."]], "tr": 51, "col": 0, "da": "Đ Đ S Đ", "lg": ["Với người trên núi quỹ đạo là nhánh parabol; với người trên máy bay (cùng vận tốc ngang) gói hàng rơi thẳng đứng. <span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 235}{9{,}8}}\\approx 6{,}93</span> s; <span class=\"m\">v_0=\\dfrac{250}{3{,}6}\\approx 69{,}4</span> m/s ⇒ <span class=\"m\">L=v_0t\\approx 480{,}9</span> m."]}, {"than": "<p>Một viên đạn được bắn theo phương nằm ngang từ một khẩu súng đặt ở độ cao 45,0 m so với mặt đất. Vận tốc của viên đạn khi vừa ra khỏi nòng súng có độ lớn là 250 m/s. Lấy g = 9,8 m/s².</p><figure><img src=\"k10-c2-mr/h/t51_1360_1630.jpg\" width=\"650\" height=\"170\" style=\"width:5.26cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Viên đạn sau khi bay khỏi nòng súng chuyển động thẳng chậm dần đều."], ["b", "Thời gian từ lúc bắt đầu chuyển động đến khi chạm đất của viên đạn 3,03 s."], ["c", "Viên đạn rơi xuống đất cách điểm bắn theo phương nằm ngang 3125 m."], ["d", "Ngay trước khi chạm đất, vận tốc của viên đạn có độ lớn bằng 252 m/s."]], "tr": 51, "col": 0, "da": "S Đ S Đ", "lg": ["Viên đạn chuyển động ném ngang (không phải thẳng chậm dần đều). <span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 45}{9{,}8}}\\approx 3{,}03</span> s; <span class=\"m\">L=250\\cdot 3{,}03\\approx 758</span> m; <span class=\"m\">v=\\sqrt{250^2+(9{,}8\\cdot 3{,}03)^2}\\approx 252</span> m/s."]}], "III": [{"than": "<p>Một hòn bi lăn dọc theo một cạnh của một mặt bàn hình chữ nhật nằm ngang cao h = 1,25 m. Lấy g = 10 m/s². Thời gian rơi của viên bi là bao nhiêu giây?</p><figure><img src=\"k10-c2-mr/h/t51_1630_2300.jpg\" width=\"330\" height=\"405\" style=\"width:2.67cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 51, "col": 0, "da": "0,5", "lg": ["<span class=\"m\">t=\\sqrt{\\dfrac{2h}{g}}=\\sqrt{\\dfrac{2\\cdot 1{,}25}{10}}=0{,}5</span> s."]}, {"than": "<p>Một vật được ném ngang từ độ cao h = 9 m, vận tốc ban đầu <span class=\"m\">v_0</span>. Vật bay xa 18 m, lấy g = 10 m/s². Tính <span class=\"m\">v_0</span> theo đơn vị m/s? (Kết quả lấy đến 1 chữ số có nghĩa).</p>", "lc": [], "ds": [], "tr": 51, "col": 0, "da": "13,4", "lg": ["<span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 9}{10}}\\approx 1{,}34</span> s ⇒ <span class=\"m\">v_0=\\dfrac{18}{1{,}34}\\approx 13{,}4</span> m/s (đề ghi \"1 chữ số có nghĩa\", hiểu là lấy 1 chữ số sau dấu phẩy)."]}, {"than": "<p>Một quả cầu được ném theo phương ngang từ độ cao 80 m so với mặt đất với <span class=\"m\">v_0=30\\ \\text{m/s}</span>. Bỏ qua sức cản của không khí. Lấy <span class=\"m\">g=10\\ \\text{m/s}^2</span>. Xác định góc (tính theo đơn vị độ) giữa vận tốc chạm đất của vật hợp với phương ngang? (Kết quả lấy đến 1 chữ số có nghĩa).</p>", "lc": [], "ds": [], "tr": 51, "col": 0, "da": "53,1", "lg": ["<span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 80}{10}}=4</span> s; <span class=\"m\">v_y=40</span> m/s; <span class=\"m\">\\tan\\alpha=\\dfrac{40}{30}</span> ⇒ <span class=\"m\">\\alpha\\approx 53{,}1^\\circ</span>."]}, {"than": "<p>Một máy bay ném bom đang bay theo phương ngang ở độ cao 2 km với <span class=\"m\">v_0=504\\ \\text{km/h}</span>. Bỏ qua sức cản của không khí. Hỏi viên phi công phải thả bom từ xa cách mục tiêu bao nhiêu km để bom rơi trúng mục tiêu? Biết bom được thả theo phương ngang, lấy g = 10 m/s².</p>", "lc": [], "ds": [], "tr": 52, "col": 0, "da": "2,8", "lg": ["<span class=\"m\">v_0=504</span> km/h <span class=\"m\">=140</span> m/s; <span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 2000}{10}}=20</span> s ⇒ <span class=\"m\">L=140\\cdot 20=2800</span> m <span class=\"m\">=2{,}8</span> km."]}, {"than": "<p>Một vật được ném theo phương ngang từ độ cao h so với mặt đất với vận tốc đầu 20 m/s, có tầm ném xa là 120 m. Bỏ qua sức cản của không khí. Lấy g = 10 m/s². Tính h theo đơn vị m.</p>", "lc": [], "ds": [], "tr": 52, "col": 0, "da": "180", "lg": ["<span class=\"m\">t=\\dfrac{L}{v_0}=\\dfrac{120}{20}=6</span> s ⇒ <span class=\"m\">h=\\dfrac12\\cdot 10\\cdot 6^2=180</span> m."]}, {"than": "<p>Một diễn viên đóng thế phải thực hiện một pha hành động khi điều khiển chiếc mô tô nhảy khỏi vách đá cao 50 m. Xe máy phải rời khỏi vách đá với tốc độ bao nhiêu m/s để tiếp đất tại vị trí cách chân vách đá 90 m. Lấy g = 9,8 m/s², bỏ qua lực cản của không khí và xem chuyển động của mô tô khi rời vách đá là chuyển động ném ngang? (Kết quả lấy đến 1 chữ số có nghĩa).</p>", "lc": [], "ds": [], "tr": 52, "col": 0, "da": "28,2", "lg": ["<span class=\"m\">t=\\sqrt{\\dfrac{2\\cdot 50}{9{,}8}}\\approx 3{,}19</span> s ⇒ <span class=\"m\">v_0=\\dfrac{90}{3{,}19}\\approx 28{,}2</span> m/s (đề ghi \"1 chữ số có nghĩa\", hiểu là lấy 1 chữ số sau dấu phẩy)."]}]}, {"ten": "Chuyển động ném xiên", "lt": "<h3 class=\"lt-h\">CHUYỂN ĐỘNG NÉM XIÊN</h3><h4>1. Chuyển động ném</h4><p><b>Bài toán: Khảo sát chuyển động của vật bị ném xiên từ độ cao h với vận tốc <span class=\"m\">\\vec{v_0}</span> xiên một góc α so với phương ngang.</b></p><p>- <b><i>Chọn hệ trục tọa độ Oxy:</i></b></p><p class=\"sub\">+ <i>Gốc O là vị trí ném vật;</i></p><p class=\"sub\">+ <i>Trục Ox theo hướng vận tốc đầu;</i></p><p class=\"sub\">+ <i>Trục Oy thẳng đứng hướng xuống.</i></p><p class=\"sub\">+ <i>Gốc thời gian lúc ném.</i></p><figure><img src=\"k10-c2-mr/h/t52_505_1600.jpg\" width=\"1175\" height=\"500\" style=\"width:9.51cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>Để khảo sát, ta phân tích chuyển động ném xiên thành hai chuyển động thành phần: chuyển động thành phần theo phương thẳng đứng Oy và chuyển động thành phần theo phương nằm ngang Ox:</p><p>- <b><i>Theo phương Ox:</i></b> <i><span class=\"m\">M_x</span> chuyển động thẳng đều với vận tốc <span class=\"m\">v_x</span>:</i> <span class=\"m\">a_x=0;\\ v_x=v_0\\cos\\alpha;\\ d_x=(v_0\\cos\\alpha)t</span> (1)</p><p>- <b><i>Theo phương Oy:</i></b> <i><span class=\"m\">M_y</span> chuyển động thẳng biến đổi đều:</i> <span class=\"m\">a_y=-g;\\ v_y=v_0\\sin\\alpha-gt;\\ d_y=(v_0\\sin\\alpha)t-\\dfrac{1}{2}gt^2</span> (2)</p><p>- <i>Phương trình quỹ đạo của vật:</i></p><div class=\"mb\">d_y=-\\dfrac{g}{2v_0^2\\cos^2\\alpha}x^2+\\tan\\alpha.x\\quad(3)</div><p>⇒ <b><i>Quỹ đạo chuyển động của vật ném xiên là một parabol</i></b></p><p>- <b>Xác định tầm bay cao của vật:</b> ta rút t ở với phương trình <span class=\"m\">v_y</span> có</p><p>Vì lên đến độ cao cực đại nên <span class=\"m\">v_y=0\\Rightarrow t_1=\\dfrac{v_0\\sin\\alpha}{g}</span> (6)</p><p>Thay (6) vào (4) với phương trình y ta có <span class=\"m\">h_{\\max}=h+\\dfrac{1}{2}\\dfrac{v_0^2\\sin^2\\alpha}{g}</span></p><p><b>Chú ý:</b> nếu h = 0 thì <span class=\"m\">h_{\\max}=\\dfrac{v_0^2\\sin^2\\alpha}{2g}</span></p><p>- <b>Xác định tầm bay xa của vật:</b></p><p>Khi trở về mặt đất y = 0</p><p>Xét phương trình y ở (4) <span class=\"m\">0=h+(v_0\\sin\\alpha)t-\\dfrac{1}{2}gt^2\\Rightarrow t=?</span></p><p>Rồi thay t vào phương trình (3) tính ra x chính là tầm xa L.</p><p class=\"sub\">+ Nếu h = 0 ta có <span class=\"m\">t_2=\\dfrac{2v_0\\sin\\alpha}{g}\\Rightarrow x=L=\\dfrac{v_0^2\\sin2\\alpha}{g}</span></p><p>⇒ <span class=\"m\">L_{\\max}</span> khi <span class=\"m\">(\\sin2\\alpha)_{\\max}=1\\Rightarrow2\\alpha=90^\\circ</span> hay <span class=\"m\">\\alpha=45^\\circ</span></p><p>- <b>Xác định vận tốc ở một vị trí</b> <span class=\"m\">v=\\sqrt{v_x^2+v_y^2}</span></p><p>- <b>Xác định độ dịch chuyển của vật so với vị trí ban gốc tọa độ</b> <span class=\"m\">d=\\sqrt{x^2+y^2}</span></p>", "I": [{"than": "<p>Một vật ném nghiêng có quỹ đạo như hình vẽ. Tầm bay xa của vật là khoảng cách giữa</p><figure><img src=\"k10-c2-mr/h/t53_1290_2430.jpg\" width=\"550\" height=\"230\" style=\"width:4.45cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "điểm ném và điểm cao nhất của quỹ đạo."], ["B", "điểm cao nhất của quỹ đạo và điểm rơi."], ["C", "điểm cao nhất của quỹ đạo và điểm có gia tốc bằng 0."], ["D", "điểm ném và điểm rơi trên mặt đất."]], "ds": [], "tr": 53, "col": 1, "da": "D", "lg": ["Tầm bay xa là khoảng cách theo phương ngang giữa điểm ném và điểm rơi (cùng độ cao)."]}, {"than": "<p>Trong hình vẽ sau,</p><figure><img src=\"k10-c2-mr/h/t54_160_200.jpg\" width=\"670\" height=\"375\" style=\"width:5.42cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>Gia tốc của vật tại đỉnh I có</p>", "lc": [["A", "hướng ngang theo chiều từ H đến I."], ["B", "hướng ngang theo chiều từ I đến H."], ["C", "hướng thẳng đứng xuống dưới."], ["D", "hướng thẳng đứng lên trên."]], "ds": [], "tr": 53, "col": 2, "da": "C", "lg": ["Gia tốc của vật ném luôn là <span class=\"m\">\\vec g</span>: hướng thẳng đứng xuống dưới, kể cả tại đỉnh I."]}, {"than": "<p>Chọn phát biểu <b>đúng</b> cho chuyển động ném xiên góc α.</p>", "lc": [["A", "Có thể phân tích thành hai chuyển động thành phần: chuyển động thẳng đều dọc trục ngang Ox với vận tốc <span class=\"m\">v_0\\cos\\alpha</span> và rơi tự do theo phương thẳng đứng."], ["B", "Chuyển động thành phần dọc trục thẳng đứng có gia tốc không đổi và luôn có dấu âm \"–\" chứng tỏ đó là chuyển động chậm dần đều."], ["C", "Chuyển động thành phần dọc trục ngang là chuyển động theo quán tính."], ["D", "Vận tốc chuyển động thành phần theo phương thẳng đứng Oy lúc đầu dương về sau âm chứng tỏ lúc đầu nhanh dần đều về sau chậm dần đều."]], "ds": [], "tr": 54, "col": 1, "da": "C", "lg": ["Theo phương ngang không có lực (bỏ qua lực cản) nên vật chuyển động thẳng đều theo quán tính. Theo phương thẳng đứng vật có vận tốc đầu <span class=\"m\">v_0\\sin\\alpha</span> nên không phải rơi tự do."]}, {"than": "<p>Một vật được ném từ mặt đất với vận tốc <span class=\"m\">\\vec{v_0}</span> nghiêng một góc α với phương ngang. Lấy g = 10 m/s². Bỏ qua sức cản không khí. Để tầm xa lớn nhất thì</p>", "lc": [["A", "<span class=\"m\">\\alpha=\\dfrac{\\pi}{4}</span>"], ["B", "<span class=\"m\">\\alpha=\\dfrac{\\pi}{3}</span>"], ["C", "<span class=\"m\">\\alpha=\\dfrac{\\pi}{2}</span>"], ["D", "<span class=\"m\">\\alpha=\\dfrac{\\pi}{6}</span>"]], "ds": [], "tr": 54, "col": 4, "da": "A", "lg": ["<span class=\"m\">L=\\dfrac{v_0^2\\sin 2\\alpha}{g}</span> lớn nhất khi <span class=\"m\">\\sin 2\\alpha=1</span> ⇒ <span class=\"m\">\\alpha=45^\\circ=\\dfrac{\\pi}{4}</span>."]}, {"than": "<p>Trong chuyển động của vật được ném xiên từ mặt đất thì đại lượng nào sau đây không đổi?</p>", "lc": [["A", "Gia tốc của vật."], ["B", "Độ cao của vật."], ["C", "Khoảng cách theo phương nằm ngang từ điểm vật được ném tới vật."], ["D", "Vận tốc của vật."]], "ds": [], "tr": 54, "col": 1, "da": "A", "lg": ["Gia tốc luôn bằng <span class=\"m\">\\vec g</span>."]}, {"than": "<p>Một vật được ném xiên từ mặt đất với vận tốc ban đầu <span class=\"m\">v_0</span> hợp với phương ngang một góc α. Tầm bay cao của vật là</p>", "lc": [["A", "<span class=\"m\">\\dfrac{v_0^2.\\sin^2\\alpha}{2g}</span>"], ["B", "<span class=\"m\">\\dfrac{v_0.\\sin2\\alpha}{2g}</span>"], ["C", "<span class=\"m\">\\dfrac{v_0^2.\\sin^22\\alpha}{g}</span>"], ["D", "<span class=\"m\">\\dfrac{v_0.\\sin^2\\alpha}{g}</span>"]], "ds": [], "tr": 54, "col": 2, "da": "A", "lg": ["<span class=\"m\">v_y=0</span> ở đỉnh: <span class=\"m\">H=\\dfrac{v_0^2\\sin^2\\alpha}{2g}</span>."]}, {"than": "<p>Biểu thức nào sau đây xác định độ cao cực đại mà vật đạt được khi ném xiên vật hợp với phương ngang một góc α từ mặt đất.</p>", "lc": [["A", "<span class=\"m\">h_{\\max}=y_{\\max}=\\dfrac{v_0\\sin^2\\alpha}{2g}</span>"], ["B", "<span class=\"m\">h_{\\max}=y_{\\max}=\\dfrac{2v_0^2\\sin^2\\alpha}{g}</span>"], ["C", "<span class=\"m\">h_{\\max}=y_{\\max}=\\dfrac{v_0^2\\sin^2\\alpha}{2g}</span>"], ["D", "<span class=\"m\">h_{\\max}=y_{\\max}=\\dfrac{v_0^2\\sin\\alpha}{2g}</span>"]], "ds": [], "tr": 54, "col": 2, "da": "C", "lg": ["<span class=\"m\">h_{\\max}=\\dfrac{v_0^2\\sin^2\\alpha}{2g}</span>."]}, {"than": "<p>Tầm xa (L) tính theo phương ngang xác định bằng biểu thức nào sau đây khi ném xiên vật hợp với phương ngang một góc α từ mặt đất.</p>", "lc": [["A", "<span class=\"m\">L=x_{\\max}=\\dfrac{2v_0.\\sin\\alpha.\\cos\\alpha}{g}</span>"], ["B", "<span class=\"m\">L=x_{\\max}=\\dfrac{2v_0.\\sin^2\\alpha.\\cos^2\\alpha}{g}</span>"], ["C", "<span class=\"m\">L=x_{\\max}=\\dfrac{2v_0^2.\\sin\\alpha.\\cos\\alpha}{g}</span>"], ["D", "<span class=\"m\">L=x_{\\max}=\\dfrac{v_0^2.\\sin\\alpha.\\cos\\alpha}{2g}</span>"]], "ds": [], "tr": 55, "col": 1, "da": "C", "lg": ["<span class=\"m\">t=\\dfrac{2v_0\\sin\\alpha}{g}</span> ⇒ <span class=\"m\">L=v_0\\cos\\alpha\\cdot t=\\dfrac{2v_0^2\\sin\\alpha\\cos\\alpha}{g}</span>."]}, {"than": "<p>Một vật được ném xiên lên từ mặt đất với vận tốc <span class=\"m\">v_0</span> và góc ném α thì tầm bay xa có biểu thức nào khi ném xiên vật hợp với phương ngang một góc α từ mặt đất.</p>", "lc": [["A", "<span class=\"m\">L=\\dfrac{v_0^2.\\sin2\\alpha}{g}</span>"], ["B", "<span class=\"m\">L=\\dfrac{v_0^2.\\sin\\alpha}{g}</span>"], ["C", "<span class=\"m\">L=\\dfrac{2v_0^2.\\sin2\\alpha}{g}</span>"], ["D", "<span class=\"m\">L=\\dfrac{2v_0^2.\\sin\\alpha}{g}</span>"]], "ds": [], "tr": 55, "col": 2, "da": "A", "lg": ["<span class=\"m\">L=\\dfrac{v_0^2\\sin 2\\alpha}{g}</span>."]}, {"than": "<p>Hai vật được đồng thời ném từ mặt đất lên với vận tốc ban đầu như Hình vẽ 12.1</p><figure><img src=\"k10-c2-mr/h/t55_815_1410.jpg\" width=\"455\" height=\"390\" style=\"width:3.68cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>Nếu bỏ qua sức cản không khí thì</p>", "lc": [["A", "Vật 1 chạm đất trước."], ["B", "Hai vật chạm đất cùng một lúc."], ["C", "Hai vật có tầm bay cao như nhau."], ["D", "Vật 1 có tầm bay cao hơn."]], "ds": [], "tr": 55, "col": 2, "da": "A", "lg": ["Hai vectơ vận tốc có cùng thành phần ngang; vật 1 có thành phần thẳng đứng nhỏ hơn nên bay thấp hơn và chạm đất trước (<span class=\"m\">t=\\dfrac{2v_{0y}}{g}</span>)."]}, {"than": "<p>Một vật được ném xiên từ mặt đất lên với vận tốc ban đầu là <span class=\"m\">v_0=10\\ \\text{m/s}</span> theo phương hợp với phương ngang một góc 30°. Cho g = 10 m/s². Độ cao cực đại vật đạt đến là</p>", "lc": [["A", "22,5 m"], ["B", "45 m"], ["C", "1,25 m"], ["D", "60 m"]], "ds": [], "tr": 55, "col": 4, "da": "C", "lg": ["<span class=\"m\">H=\\dfrac{v_0^2\\sin^2\\alpha}{2g}=\\dfrac{10^2\\cdot 0{,}5^2}{2\\cdot 10}=1{,}25</span> m."]}, {"than": "<p>Một vật được ném xiên từ mặt đất lên với vận tốc ban đầu là <span class=\"m\">v_0=10\\ \\text{m/s}</span> theo phương hợp với phương ngang một góc 30°. Cho g = 10 m/s². Tầm bay xa của vật là</p>", "lc": [["A", "8,66 m"], ["B", "4,33 m"], ["C", "5 m"], ["D", "10 m"]], "ds": [], "tr": 55, "col": 4, "da": "A", "lg": ["<span class=\"m\">L=\\dfrac{v_0^2\\sin 2\\alpha}{g}=\\dfrac{100\\cdot\\sin 60^\\circ}{10}\\approx 8{,}66</span> m."]}, {"than": "<p>Một quả banh được người chơi gôn đánh đi với vận tốc đầu là <span class=\"m\">v_0=40\\ \\text{m/s}</span> hợp với phương ngang một góc α = 45°. Quả banh bay về hướng hồ cách đó 100 m, hồ rộng 50 m. Lấy g = 10 m/s². Xác định quỹ đạo của quả banh (chọn gốc tọa độ O tại chỗ đánh quả banh, chiều dương Oy hướng lên, chiều dương Ox về phía hồ).</p>", "lc": [["A", "<span class=\"m\">y=-\\dfrac{1}{40}x^2+x</span>"], ["B", "<span class=\"m\">y=\\dfrac{1}{40}x^2+x</span>"], ["C", "<span class=\"m\">y=-\\dfrac{1}{160}x^2+x</span>"], ["D", "<span class=\"m\">y=\\dfrac{1}{60}x^2+x</span>"]], "ds": [], "tr": 55, "col": 4, "da": "C", "lg": ["<span class=\"m\">y=-\\dfrac{g}{2v_0^2\\cos^2\\alpha}x^2+x\\tan\\alpha=-\\dfrac{10}{2\\cdot 1600\\cdot 0{,}5}x^2+x=-\\dfrac{x^2}{160}+x</span>."]}, {"than": "<p>Một trái bóng được đá đi từ mặt đất với góc nghiêng đối với mặt phẳng ngang được tính sao cho bóng bay xa nhất. Tầm bay xa mà bóng bay được bằng 62,5 m theo phương ngang. Cho g = 10 m/s². Vận tốc ban đầu của trái bóng có độ lớn là:</p>", "lc": [["A", "20 m/s"], ["B", "25 m/s"], ["C", "30 m/s"], ["D", "35 m/s"]], "ds": [], "tr": 56, "col": 4, "da": "B", "lg": ["Bay xa nhất khi <span class=\"m\">\\alpha=45^\\circ</span>: <span class=\"m\">L_{\\max}=\\dfrac{v_0^2}{g}=62{,}5</span> ⇒ <span class=\"m\">v_0=25</span> m/s."]}, {"than": "<p>Một quả bóng được đá đi từ mặt đất với vận tốc có độ lớn bằng 10 m/s theo phương hợp với phương ngang một góc α. Khi chạm đất, vận tốc của bóng có độ lớn:</p>", "lc": [["A", "10 m/s"], ["B", "(10cosα) m/s"], ["C", "(10sinα) m/s"], ["D", "(10tanα) m/s."]], "ds": [], "tr": 56, "col": 4, "da": "A", "lg": ["Ném và chạm đất ở cùng độ cao, bỏ qua lực cản: <span class=\"m\">v_x</span> không đổi, <span class=\"m\">v_y</span> đổi dấu nhưng cùng độ lớn ⇒ <span class=\"m\">v=10</span> m/s."]}, {"than": "<p>Khi đẩy tạ, muốn quả tạ bay xa nhất thì người vận động viên phải ném tạ hợp với phương ngang một góc</p>", "lc": [["A", "30°"], ["B", "45°"], ["C", "60°"], ["D", "90°."]], "ds": [], "tr": 56, "col": 4, "da": "B", "lg": ["Bỏ qua lực cản và độ cao điểm ném, tầm xa lớn nhất khi ném nghiêng góc 45°."]}, {"than": "<p>Từ độ cao 7,5 m một quả cầu được ném lên xiên góc α = 45° so với phương ngang với vận tốc 10 m/s. Quả cầu chạm đất cách vị trí ném là</p>", "lc": [["A", "x = 15 m"], ["B", "x = 10 m"], ["C", "x = 25 m"], ["D", "x = 30 m"]], "ds": [], "tr": 56, "col": 4, "da": "A", "lg": ["<span class=\"m\">v_{0x}=v_{0y}=5\\sqrt2</span> m/s. Chạm đất: <span class=\"m\">7{,}5+5\\sqrt2\\,t-5t^2=0</span> ⇒ <span class=\"m\">t=1{,}5\\sqrt2</span> s ⇒ <span class=\"m\">x=5\\sqrt2\\cdot 1{,}5\\sqrt2=15</span> m."]}, {"than": "<p>Sườn đồi có thể coi là mặt phẳng nghiêng góc α = 60° so với mặt phẳng ngang. Lấy g = 10 m/s². Từ điểm O trên đỉnh đồi người ta ném một vật nặng với vận tốc ban đầu 10 m/s theo phương ngang, nó rơi tại điểm A trên sườn đồi. Giá trị OA bằng</p>", "lc": [["A", "1,33 m"], ["B", "16,7 m"], ["C", "50,7 m"], ["D", "69,3 m"]], "ds": [], "tr": 56, "col": 4, "da": "D", "lg": ["Rơi trên sườn nghiêng 60°: <span class=\"m\">\\tan 60^\\circ=\\dfrac{y}{x}=\\dfrac{gt}{2v_0}</span> ⇒ <span class=\"m\">t=\\dfrac{2\\cdot 10\\sqrt3}{10}=2\\sqrt3</span> s; <span class=\"m\">x=v_0t\\approx 34{,}6</span> m ⇒ <span class=\"m\">OA=\\dfrac{x}{\\cos 60^\\circ}\\approx 69{,}3</span> m."]}], "II": [{"than": "<p>Một vật được ném từ một điểm M ở độ cao h = 45 m với vận tốc ban đầu <span class=\"m\">v_0=20\\ \\text{m/s}</span> lên trên theo phương hợp với phương nằm ngang một góc 45°. Lấy <span class=\"m\">g=10\\ \\text{m/s}^2</span>, bỏ qua lực cản của không khí.</p>", "lc": [], "ds": [["a", "Phương trình quỹ đạo chuyển động của vật là ⇒ <span class=\"m\">y=45+x-\\dfrac{x^2}{40}</span>."], ["b", "Tọa độ vật sau khi ném 1 s là <span class=\"m\">x=5\\sqrt{2}\\ (\\text{m})</span>, <span class=\"m\">y\\approx54{,}14\\ (\\text{m})</span>."], ["c", "Độ cao cực đại vật đạt được so với mặt đất là 55 m."], ["d", "Thời gian vật bay trong không khí là 2 s."]], "tr": 56, "col": 0, "da": "Đ S Đ S", "lg": ["Gốc O ở mặt đất ngay dưới M, Oy hướng lên: <span class=\"m\">y=45+x-\\dfrac{x^2}{40}</span>. Sau 1 s: <span class=\"m\">x=20\\cos 45^\\circ\\cdot 1=10\\sqrt2\\approx 14{,}14</span> m (không phải <span class=\"m\">5\\sqrt2</span>), <span class=\"m\">y\\approx 54{,}14</span> m. <span class=\"m\">h_{\\max}=45+\\dfrac{20^2\\cdot 0{,}5}{20}=55</span> m. Chạm đất: <span class=\"m\">45+10\\sqrt2\\,t-5t^2=0</span> ⇒ <span class=\"m\">t\\approx 4{,}73</span> s."]}, {"than": "<p>Một vận động viên ném đĩa cao đang luyện tập. Vận động viên ném đĩa với vận tốc ban đầu <span class=\"m\">v_0</span> lên trên theo phương hợp với phương nằm ngang một góc 45°, đĩa rời tay vận động viên ở độ cao 1,7 m. Đĩa rơi cách vận động viên 60 m. Thời gian từ lúc ném đến lúc đĩa chạm đất là <span class=\"m\">3\\sqrt{2}</span> (s). Lấy g = 10 m/s², bỏ qua lực cản của không khí.</p>", "lc": [], "ds": [["a", "Quỹ đạo chuyển động của đĩa có dạng là một nhánh của Hyperbol."], ["b", "Vận tốc ban đầu của đĩa ném là <span class=\"m\">v_0=20</span> m/s."], ["c", "Độ cao cực đại mà đĩa đạt được so với mặt đất là 11,7 m."], ["d", "Vận tốc lúc chạm đất của đĩa là 40 m/s."]], "tr": 56, "col": 0, "da": "S Đ Đ S", "lg": ["Quỹ đạo là một nhánh parabol. <span class=\"m\">v_0\\cos 45^\\circ=\\dfrac{60}{3\\sqrt2}=10\\sqrt2</span> ⇒ <span class=\"m\">v_0=20</span> m/s. <span class=\"m\">h_{\\max}=1{,}7+\\dfrac{20^2\\cdot 0{,}5}{20}=11{,}7</span> m. Khi chạm đất <span class=\"m\">v=\\sqrt{v_0^2+2gh_0}=\\sqrt{400+34}\\approx 20{,}8</span> m/s, không phải 40 m/s. (Lưu ý: số liệu của đề chưa khớp nhau; với <span class=\"m\">v_0=20</span> m/s thì đĩa chỉ bay khoảng 2,94 s và xa khoảng 41,6 m.)"]}, {"than": "<p>Một vật được ném từ một điểm M ở độ cao h = 45 m với vận tốc ban đầu <span class=\"m\">v_0=20</span> m/s xiên lên theo phương hợp với phương nằm ngang một góc 45°. Lấy g = 10 m/s², bỏ qua lực cản của không khí.</p>", "lc": [], "ds": [["a", "Tầm bay xa của vật là 66,89 (m)."], ["b", "Vận tốc của vật khi chạm đất là 30 m/s."], ["c", "Phương trình quỹ đạo của vật là <span class=\"m\">y=x-\\dfrac{1}{40}x^2</span> (m)."], ["d", "Độ dịch chuyển của vật từ lúc ném đến lúc chạm đất là 80,61 m."]], "tr": 57, "col": 0, "da": "Đ S Đ Đ", "lg": ["<span class=\"m\">t\\approx 4{,}73</span> s ⇒ <span class=\"m\">L=10\\sqrt2\\cdot 4{,}73\\approx 66{,}9</span> m. <span class=\"m\">v=\\sqrt{v_0^2+2gh}=\\sqrt{400+900}\\approx 36{,}1</span> m/s. Gốc tọa độ tại M, Oy hướng lên: <span class=\"m\">y=x-\\dfrac{x^2}{40}</span>. Độ dịch chuyển <span class=\"m\">\\sqrt{66{,}89^2+45^2}\\approx 80{,}6</span> m."]}, {"than": "<p>Từ mặt đất một quả cầu được ném theo phương hướng lên hợp với phương ngang một góc 60° với vận tốc 20 m/s.</p>", "lc": [], "ds": [["a", "Phương trình quỹ đạo của quả cầu là <span class=\"m\">y=\\sqrt{3}x-\\dfrac{x^2}{20}</span> (cm)."], ["b", "Độ cao cực đại vật đạt được so với mặt đất là 10 m."], ["c", "Tầm bay xa của vật là <span class=\"m\">20\\sqrt{3}</span> (cm)."], ["d", "Vận tốc của vật lúc chạm đất là 10 m/s."]], "tr": 57, "col": 0, "da": "S S S S", "lg": ["<span class=\"m\">y=\\sqrt3x-\\dfrac{10}{2\\cdot 400\\cdot 0{,}25}x^2=\\sqrt3x-\\dfrac{x^2}{20}</span> với x, y tính bằng <b>m</b> (ý a, c ghi cm nên sai). <span class=\"m\">H=\\dfrac{400\\cdot 0{,}75}{20}=15</span> m. <span class=\"m\">L=\\dfrac{400\\sin 120^\\circ}{10}=20\\sqrt3</span> m. Chạm đất cùng độ cao nên <span class=\"m\">v=20</span> m/s."]}], "III": [{"than": "<p>Một vật được ném xiên từ mặt đất với vận tốc ban đầu có độ lớn <span class=\"m\">v_0=50</span> m/s. Khi lên tới điểm cao nhất, vận tốc của vật có độ lớn là 40 m/s. Bỏ qua sức cản của không khí, lấy <span class=\"m\">g=10\\ \\text{m/s}^2</span>. Góc ném α so với phương ngang bằng bao nhiêu độ? (Kết quả lấy sau dấu phẩy 1 chữ số thập phân)</p>", "lc": [], "ds": [], "tr": 57, "col": 0, "da": "36,9", "lg": ["Ở điểm cao nhất <span class=\"m\">v=v_0\\cos\\alpha=40</span> ⇒ <span class=\"m\">\\cos\\alpha=0{,}8</span> ⇒ <span class=\"m\">\\alpha\\approx 36{,}9^\\circ</span>."]}, {"than": "<p>Một cầu thủ bóng rổ cao 2 m đứng cách xa rổ 10 m theo phương nằm ngang để tập ném bóng vào rổ. Biết miệng rổ ở độ cao 3,05 m. Hỏi người đó phải ném bóng từ độ cao ngang đầu với vận tốc theo phương 45° có độ lớn bao nhiêu m/s để bóng đi vào rổ? Lấy <span class=\"m\">g=9{,}8\\ \\text{m/s}^2</span>. (Kết quả lấy sau dấu phẩy 1 chữ số thập phân)</p>", "lc": [], "ds": [], "tr": 57, "col": 0, "da": "10,5", "lg": ["Gốc tại tay ném (cao 2 m): <span class=\"m\">y=x\\tan 45^\\circ-\\dfrac{gx^2}{2v_0^2\\cos^2 45^\\circ}</span>. Với <span class=\"m\">x=10</span> m, <span class=\"m\">y=1{,}05</span> m: <span class=\"m\">1{,}05=10-\\dfrac{9{,}8\\cdot 100}{v_0^2}</span> ⇒ <span class=\"m\">v_0\\approx 10{,}5</span> m/s."]}, {"than": "<p>Khi dùng vòi nước tưới cây, để các tia nước phun ra xa, người ta thường điều chỉnh sao cho hướng của vòi xiên một góc nào đó với phương ngang (Hình 9.2). Trong trường hợp lí tưởng (bỏ qua mọi lực cản), góc hợp giữa vòi và phương ngang phải bằng bao nhiêu độ để các tia nước phun ra xa nhất?</p><figure><img src=\"k10-c2-mr/h/t57_740_2365.jpg\" width=\"565\" height=\"410\" style=\"width:4.57cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 57, "col": 0, "da": "45", "lg": ["Bỏ qua lực cản, tầm xa <span class=\"m\">L=\\dfrac{v_0^2\\sin 2\\alpha}{g}</span> lớn nhất khi <span class=\"m\">\\alpha=45^\\circ</span>."]}, {"than": "<p>Một diễn viên biểu diễn mô tô bay đang phóng xe trên mặt dốc nằm nghiêng 30° để bay qua các ô tô như trong hình 12.3. Biết vận tốc của xe mô tô khi rời khỏi đỉnh dốc là 14 m/s. Chiều cao</p><p>của ô tô bằng chiều cao của dốc, chiều dài của ô tô là 3,2 m. Lấy g = 10 m/s². Thời gian từ khi xe rời đỉnh dốc tới khi đạt độ cao cực đại là bao nhiêu giây? (Kết quả lấy sau dấu phẩy 2 chữ số thập phân)</p><figure><img src=\"k10-c2-mr/h/t58_570_410.jpg\" width=\"1070\" height=\"310\" style=\"width:8.66cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "tr": 57, "col": 0, "da": "0,70", "lg": ["<span class=\"m\">t=\\dfrac{v_0\\sin 30^\\circ}{g}=\\dfrac{14\\cdot 0{,}5}{10}=0{,}70</span> s."]}, {"than": "<p>Từ mặt đất một quả cầu được ném theo phương hướng lên hợp với phương ngang một góc 60° với vận tốc 30 m/s. Tầm ném xa của quả cầu là bao nhiêu mét? Kết quả lấy sau dấu phẩy 1 chữ số thập phân.</p>", "lc": [], "ds": [], "tr": 58, "col": 0, "da": "77,9", "lg": ["<span class=\"m\">L=\\dfrac{v_0^2\\sin 2\\alpha}{g}=\\dfrac{900\\cdot\\sin 120^\\circ}{10}\\approx 77{,}9</span> m."]}, {"than": "<p>Từ mặt đất một vật được ném xiên lệch với phương ngang một góc α = 45° với vận tốc ban đầu là 20 m/s. Lấy g = 10 m/s². Tầm bay cao của vật là bao nhiêu mét?</p>", "lc": [], "ds": [], "tr": 58, "col": 0, "da": "10", "lg": ["<span class=\"m\">H=\\dfrac{v_0^2\\sin^2\\alpha}{2g}=\\dfrac{400\\cdot 0{,}5}{20}=10</span> m."]}]}], "dem": {"I": 36, "II": 8, "III": 12}, "word": "k10-c2-mr/word/Bai12_Chuyen_dong_nem_Mo_rong.docx", "wordDa": "k10-c2-mr/word/Bai12_Chuyen_dong_nem_Mo_rong_Dap_an.docx"}};
